                ELSE
                    RETURN jsonb_build_object(
                        'errors', jsonb_build_array(
                            jsonb_build_object(
                                'message', 'pg_graphql is only available on projects running Postgres 14 onwards.'
                            )
                        )
                    );
                END IF;
            END;
        $$;


ALTER FUNCTION graphql_public.graphql("operationName" text, query text, variables jsonb, extensions jsonb) OWNER TO supabase_admin;

--
-- Name: get_auth(text); Type: FUNCTION; Schema: pgbouncer; Owner: supabase_admin
--

CREATE FUNCTION pgbouncer.get_auth(p_usename text) RETURNS TABLE(username text, password text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
  BEGIN
      RAISE DEBUG 'PgBouncer auth request: %', p_usename;

      RETURN QUERY
      SELECT
          rolname::text,
          CASE WHEN rolvaliduntil < now()
              THEN null
              ELSE rolpassword::text
          END
      FROM pg_authid
      WHERE rolname=$1 and rolcanlogin;
  END;
  $_$;


ALTER FUNCTION pgbouncer.get_auth(p_usename text) OWNER TO supabase_admin;

--
-- Name: create_hive_with_queen(uuid, uuid, text, public.hive_type, public.bee_race, date, text, smallint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_hive_with_queen(p_id uuid, p_apiary_id uuid, p_identifier text, p_hive_type public.hive_type, p_bee_race public.bee_race, p_installed_on date, p_origin_notes text, p_nido_frame_count smallint, p_notes text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM apiaries WHERE id = p_apiary_id AND owner_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'unauthorized';
  END IF;

  INSERT INTO hives (
    id, apiary_id, identifier, hive_type, bee_race,
    installed_on, origin_notes, nido_frame_count, notes
  ) VALUES (
    p_id, p_apiary_id, p_identifier, p_hive_type, p_bee_race,
    p_installed_on, p_origin_notes, p_nido_frame_count, p_notes
  );

  INSERT INTO queens (hive_id, origin, start_date)
  VALUES (p_id, 'sconosciuta', COALESCE(p_installed_on, CURRENT_DATE));
END;
$$;


ALTER FUNCTION public.create_hive_with_queen(p_id uuid, p_apiary_id uuid, p_identifier text, p_hive_type public.hive_type, p_bee_race public.bee_race, p_installed_on date, p_origin_notes text, p_nido_frame_count smallint, p_notes text) OWNER TO postgres;

--
-- Name: get_active_user_counts(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_active_user_counts() RETURNS TABLE(active_7d bigint, active_30d bigint)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select
    count(distinct case when created_at >= now() - interval '7 days' then user_id end) as active_7d,
    count(distinct case when created_at >= now() - interval '30 days' then user_id end) as active_30d
  from activity_log
  where created_at >= now() - interval '30 days';
$$;


ALTER FUNCTION public.get_active_user_counts() OWNER TO postgres;

--
-- Name: get_api_cost_by_user(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_api_cost_by_user() RETURNS TABLE(user_id uuid, display_name text, call_count bigint, cost_usd numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select
    l.user_id,
    coalesce(p.display_name, l.user_id::text) as display_name,
    count(*)::bigint as call_count,
    sum(l.cost_usd) as cost_usd
  from api_usage_log l
  left join profiles p on p.id = l.user_id
  group by l.user_id, p.display_name
  order by cost_usd desc;
$$;


ALTER FUNCTION public.get_api_cost_by_user() OWNER TO postgres;

--
-- Name: get_storage_usage(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_storage_usage(bucket_name text) RETURNS TABLE(total_size bigint, total_files bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  return query
  select
    coalesce(sum((metadata->>'size')::bigint), 0)::bigint as total_size,
    count(*)::bigint as total_files
  from storage.objects
  where bucket_id = bucket_name;
end;
$$;


ALTER FUNCTION public.get_storage_usage(bucket_name text) OWNER TO postgres;

--
-- Name: get_user_activity_stats(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_user_activity_stats() RETURNS TABLE(user_id uuid, display_name text, inspection_count bigint, last_inspection_at timestamp with time zone, last_active_at timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select
    p.id as user_id,
    p.display_name,
    count(distinct i.id) as inspection_count,
    max(i.performed_at) as last_inspection_at,
    max(al.created_at) as last_active_at
  from profiles p
  left join inspections i on i.performed_by = p.id
  left join activity_log al on al.user_id = p.id
  group by p.id, p.display_name
  order by last_active_at desc nulls last
  limit 50;
$$;


ALTER FUNCTION public.get_user_activity_stats() OWNER TO postgres;

--
-- Name: get_weekly_inspection_counts(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_weekly_inspection_counts(weeks_back integer DEFAULT 8) RETURNS TABLE(week_start date, count bigint)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select
    date_trunc('week', performed_at)::date as week_start,
    count(*) as count
  from inspections
  where performed_at >= date_trunc('week', now()) - ((weeks_back - 1) * interval '1 week')
  group by date_trunc('week', performed_at)
  order by week_start;
$$;


ALTER FUNCTION public.get_weekly_inspection_counts(weeks_back integer) OWNER TO postgres;

