--
-- Name: storage_can_delete_apiary_media(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.storage_can_delete_apiary_media(object_name text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT auth.uid() IS NOT NULL
    AND (
      public.user_owns_apiary(public.storage_get_apiary_id(object_name))
      OR EXISTS (
        SELECT 1 FROM storage.objects
        WHERE name = object_name
          AND bucket_id = 'apidiario-media'
          AND owner = auth.uid()
      )
    );
$$;


ALTER FUNCTION public.storage_can_delete_apiary_media(object_name text) OWNER TO postgres;

--
-- Name: storage_can_delete_hive_media(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.storage_can_delete_hive_media(object_name text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  parts text[];
  hive_id uuid;
BEGIN
  parts := string_to_array(object_name, '/');
  IF parts[1] != 'hives' THEN
    RETURN FALSE;
  END IF;
  hive_id := parts[2]::uuid;
  RETURN EXISTS (
    SELECT 1 FROM hives h
    JOIN apiaries a ON a.id = h.apiary_id
    WHERE h.id = hive_id
      AND a.owner_id = (select auth.uid())
  );
END;
$$;


ALTER FUNCTION public.storage_can_delete_hive_media(object_name text) OWNER TO postgres;

--
-- Name: storage_can_delete_inspection_media(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.storage_can_delete_inspection_media(object_name text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  parts text[];
  insp_id uuid;
BEGIN
  parts := string_to_array(object_name, '/');
  IF parts[1] != 'inspections' THEN
    RETURN FALSE;
  END IF;
  insp_id := parts[2]::uuid;
  RETURN auth.uid() IS NOT NULL
    AND (
      EXISTS (
        SELECT 1 FROM inspections i
        JOIN hives h ON h.id = i.hive_id
        WHERE i.id = insp_id
          AND public.user_can_write_hive(h.id)
      )
      OR EXISTS (
        SELECT 1 FROM storage.objects
        WHERE name = object_name
          AND bucket_id = 'apidiario-media'
          AND owner = auth.uid()
      )
    );
END;
$$;


ALTER FUNCTION public.storage_can_delete_inspection_media(object_name text) OWNER TO postgres;

