    CONSTRAINT inspections_check CHECK ((((varroa_count IS NULL) AND (varroa_count_method IS NULL)) OR ((varroa_count IS NOT NULL) AND (varroa_count_method IS NOT NULL)))),
    CONSTRAINT inspections_honey_frame_count_check CHECK (((honey_frame_count >= 0) AND (honey_frame_count <= 30))),
    CONSTRAINT inspections_pollen_frame_count_check CHECK (((pollen_frame_count >= 0) AND (pollen_frame_count <= 30)))
);


