--
-- Name: media; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.media (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    kind public.media_kind NOT NULL,
    storage_path text NOT NULL,
    thumbnail_path text,
    caption text,
    apiary_id uuid,
    hive_id uuid,
    inspection_id uuid,
    uploaded_by uuid,
    size_bytes bigint,
    width integer,
    height integer,
    duration_seconds integer,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT media_size_bytes_check CHECK ((size_bytes > 0)),
    CONSTRAINT media_target_exclusive CHECK ((((
CASE
    WHEN (apiary_id IS NOT NULL) THEN 1
    ELSE 0
END +
CASE
    WHEN (hive_id IS NOT NULL) THEN 1
    ELSE 0
END) +
CASE
    WHEN (inspection_id IS NOT NULL) THEN 1
    ELSE 0
END) = 1))
);


