--
-- Data for Name: schema_migrations; Type: TABLE DATA; Schema: supabase_migrations; Owner: postgres
--

COPY supabase_migrations.schema_migrations (version, statements, name) FROM stdin;
20260502000000	{"-- =====================================================================\n-- Apidiario — Schema PostgreSQL per Supabase\n-- =====================================================================\n-- Versione:  0.1\n-- Target:    Supabase (PostgreSQL 15)\n-- Convenz.:  snake_case, UUID PK, RLS-first, soft-delete dove sensato\n-- Encoding:  UTF-8\n--\n-- Questo file è pensato per essere eseguito una sola volta come\n-- migrazione iniziale. Le evoluzioni successive andranno in file\n-- separati dentro /supabase/migrations.\n-- =====================================================================\n\n\n-- =====================================================================\n-- 1. ESTENSIONI\n-- =====================================================================\n\n-- pgcrypto: per gen_random_uuid() (in realtà PG 13+ lo ha nativo,\n-- ma su Supabase è abilitato di default tramite questa estensione).\ncreate extension if not exists \\"pgcrypto\\"","-- =====================================================================\n-- 2. ENUM\n-- =====================================================================\n-- Scelgo enum nativi per i valori stabili. Per cose che potrebbero\n-- crescere nel tempo (tipi di miele, prodotti antivarroa) uso TEXT\n-- con CHECK constraint, così aggiungere un valore non richiede una\n-- migrazione di tipo.\n\ncreate type access_role as enum ('reader', 'editor')","create type hive_status as enum (\n  'attiva',\n  'sciamata',\n  'morta',\n  'riunita',\n  'venduta',\n  'ceduta'\n)","create type hive_type as enum (\n  'dadant_blatt',\n  'langstroth',\n  'top_bar',\n  'altro'\n)","create type bee_race as enum (\n  'ligustica',\n  'buckfast',\n  'carnica',\n  'sicula',\n  'ibrida',\n  'sconosciuta'\n)","create type queen_origin as enum (\n  'figlia',\n  'introdotta',\n  'sciamatura',\n  'sostituzione_spontanea',\n  'sconosciuta'\n)","create type queen_marking_color as enum (\n  'bianco',  -- anni terminanti con 1 o 6\n  'giallo',  -- anni terminanti con 2 o 7\n  'rosso',   -- anni terminanti con 3 o 8\n  'verde',   -- anni terminanti con 4 o 9\n  'blu',     -- anni terminanti con 5 o 0\n  'non_marcata'\n)","create type queen_seen_state as enum (\n  'vista',\n  'non_vista',\n  'non_cercata'\n)","create type population_strength as enum (\n  'debole',\n  'media',\n  'forte'\n)","create type behavior_type as enum (\n  'calmo',\n  'nervoso',\n  'aggressivo'\n)","create type queen_cells_type as enum (\n  'nessuna',\n  'scorta',         -- celle di scorta o di emergenza\n  'sciamatura',     -- segno di sciamatura imminente\n  'sostituzione'    -- regina vecchia o malata\n)","create type pathology as enum (\n  'varroa',\n  'peste_americana',\n  'peste_europea',\n  'covata_calcificata',\n  'nosema',\n  'virus',\n  'altro'\n)","create type varroa_count_method as enum (\n  'caduta_naturale',\n  'lavaggio_alcol',\n  'zucchero_velo',\n  'altro'\n)","create type media_kind as enum (\n  'photo',\n  'video'\n)","create type reminder_recurrence as enum (\n  'none',\n  'weekly',\n  'monthly',\n  'yearly'\n)","create type reminder_scope as enum (\n  'global',  -- promemoria personale non legato a risorse\n  'apiary',\n  'hive'\n)","-- =====================================================================\n-- 3. FUNZIONI HELPER PER I TRIGGER\n-- =====================================================================\n\n-- Aggiorna automaticamente updated_at a ogni UPDATE.\ncreate or replace function public.trigger_set_timestamp()\nreturns trigger\nlanguage plpgsql\nas $$\nbegin\n  new.updated_at = now();\n  return new;\nend;\n$$","-- =====================================================================\n-- 4. PROFILI UTENTE\n-- =====================================================================\n-- auth.users è gestita da Supabase Auth e non si tocca.\n-- profiles estende auth.users con dati visibili agli altri membri\n-- (display name) e si crea automaticamente alla registrazione.\n\ncreate table public.profiles (\n  id           uuid primary key references auth.users(id) on delete cascade,\n  display_name text not null,\n  avatar_url   text,\n  created_at   timestamptz not null default now(),\n  updated_at   timestamptz not null default now()\n)","comment on table public.profiles is\n  'Profilo applicativo dell''utente. Una riga per ogni auth.users.'","-- Trigger: crea automaticamente il profilo alla registrazione,\n-- usando l''email come display_name iniziale (l''utente potrà cambiarlo).\ncreate or replace function public.handle_new_user()\nreturns trigger\nlanguage plpgsql\nsecurity definer set search_path = public\nas $$\nbegin\n  insert into public.profiles (id, display_name)\n  values (new.id, coalesce(new.raw_user_meta_data->>'display_name', new.email));\n  return new;\nend;\n$$","create trigger on_auth_user_created\n  after insert on auth.users\n  for each row execute function public.handle_new_user()","create trigger profiles_set_timestamp\n  before update on public.profiles\n  for each row execute function public.trigger_set_timestamp()","-- =====================================================================\n-- 5. APIARI\n-- =====================================================================\n\ncreate table public.apiaries (\n  id                 uuid primary key default gen_random_uuid(),\n  owner_id           uuid not null references public.profiles(id) on delete restrict,\n  name               text not null check (length(name) between 1 and 100),\n  -- posizione opzionale: alcuni apicoltori non vogliono salvarla\n  latitude           numeric(9, 6) check (latitude  between -90  and  90),\n  longitude          numeric(9, 6) check (longitude between -180 and 180),\n  address            text,\n  bda_codice_aziendale text,  -- codice azienda apistica (BDA)\n  notes              text,\n  archived_at        timestamptz,  -- soft delete\n  created_at         timestamptz not null default now(),\n  updated_at         timestamptz not null default now()\n)","comment on table public.apiaries is\n  'Apiari posseduti dagli utenti. Soft-delete via archived_at.'","create trigger apiaries_set_timestamp\n  before update on public.apiaries\n  for each row execute function public.trigger_set_timestamp()","-- =====================================================================\n-- 6. CONDIVISIONI APIARIO\n-- =====================================================================\n\ncreate table public.apiary_access (\n  apiary_id  uuid not null references public.apiaries(id) on delete cascade,\n  user_id    uuid not null references public.profiles(id) on delete cascade,\n  role       access_role not null,\n  granted_by uuid not null references public.profiles(id),\n  granted_at timestamptz not null default now(),\n  primary key (apiary_id, user_id)\n)","comment on table public.apiary_access is\n  'Accessi su un intero apiario. L''owner non compare qui: è gestito '\n  'dal campo apiaries.owner_id.'","-- =====================================================================\n-- 7. INVITI APIARIO (utenti non ancora registrati)\n-- =====================================================================\n\ncreate table public.apiary_invites (\n  id          uuid primary key default gen_random_uuid(),\n  apiary_id   uuid not null references public.apiaries(id) on delete cascade,\n  email       text not null check (email ~* '^[^@]+@[^@]+\\\\.[^@]+$'),\n  role        access_role not null,\n  invited_by  uuid not null references public.profiles(id),\n  token       uuid not null default gen_random_uuid(),\n  created_at  timestamptz not null default now(),\n  accepted_at timestamptz,\n  expires_at  timestamptz not null default (now() + interval '14 days'),\n  unique (apiary_id, email)\n)","comment on table public.apiary_invites is\n  'Inviti pendenti per email. Quando l''utente si registra con la '\n  'stessa email, una funzione converte l''invito in apiary_access.'","-- =====================================================================\n-- 8. ARNIE\n-- =====================================================================\n\ncreate table public.hives (\n  id                  uuid primary key default gen_random_uuid(),\n  apiary_id           uuid not null references public.apiaries(id) on delete restrict,\n  -- identificativo testuale, univoco DENTRO l''apiario\n  identifier          text not null check (length(identifier) between 1 and 50),\n  hive_type           hive_type not null default 'dadant_blatt',\n  bee_race            bee_race not null default 'sconosciuta',\n  status              hive_status not null default 'attiva',\n  installed_on        date,\n  origin_notes        text,  -- es: \\"sciame catturato 2024-04-12 in giardino vicino\\"\n  nido_frame_count    smallint not null default 10\n                       check (nido_frame_count between 1 and 30),\n  notes               text,\n  archived_at         timestamptz,\n  created_at          timestamptz not null default now(),\n  updated_at          timestamptz not null default now(),\n  unique (apiary_id, identifier)\n)","comment on table public.hives is\n  'Arnie. L''identifier (es. \\"A1\\", \\"12\\") è univoco solo all''interno '\n  'dell''apiario di appartenenza.'","create trigger hives_set_timestamp\n  before update on public.hives\n  for each row execute function public.trigger_set_timestamp()","-- =====================================================================\n-- 9. CONDIVISIONI ARNIA (granulare)\n-- =====================================================================\n\ncreate table public.hive_access (\n  hive_id    uuid not null references public.hives(id) on delete cascade,\n  user_id    uuid not null references public.profiles(id) on delete cascade,\n  role       access_role not null,\n  granted_by uuid not null references public.profiles(id),\n  granted_at timestamptz not null default now(),\n  primary key (hive_id, user_id)\n)","comment on table public.hive_access is\n  'Accesso a una singola arnia. Si somma agli accessi via apiary_access.'","-- =====================================================================\n-- 10. STORIA REGINE\n-- =====================================================================\n\ncreate table public.queens (\n  id              uuid primary key default gen_random_uuid(),\n  hive_id         uuid not null references public.hives(id) on delete cascade,\n  birth_year      smallint check (birth_year between 1990 and 2100),\n  marking_color   queen_marking_color not null default 'non_marcata',\n  origin          queen_origin not null default 'sconosciuta',\n  start_date      date not null default current_date,\n  end_date        date,  -- null = regina attuale\n  end_reason      text,\n  notes           text,\n  created_at      timestamptz not null default now(),\n  updated_at      timestamptz not null default now(),\n  check (end_date is null or end_date >= start_date)\n)","comment on table public.queens is\n  'Storia delle regine di ciascuna arnia. La regina attuale ha end_date NULL.'","-- Vincolo: una sola regina attiva per arnia.\ncreate unique index queens_one_active_per_hive\n  on public.queens (hive_id)\n  where end_date is null","create trigger queens_set_timestamp\n  before update on public.queens\n  for each row execute function public.trigger_set_timestamp()","-- =====================================================================\n-- 11. ISPEZIONI\n-- =====================================================================\n\ncreate table public.inspections (\n  id                    uuid primary key default gen_random_uuid(),\n  hive_id               uuid not null references public.hives(id) on delete cascade,\n  performed_at          timestamptz not null default now(),\n  performed_by          uuid not null references public.profiles(id),\n\n  -- meteo (auto da API se disponibile, altrimenti manuale)\n  weather_summary       text,\n  temperature_c         numeric(4, 1),\n\n  -- regina e covata\n  queen_seen            queen_seen_state not null default 'non_cercata',\n  brood_eggs            boolean,\n  brood_larvae          boolean,\n  brood_capped          boolean,\n  brood_frame_count     smallint check (brood_frame_count between 0 and 30),\n\n  -- scorte e popolazione\n  honey_frame_count     smallint check (honey_frame_count between 0 and 30),\n  pollen_frame_count    smallint check (pollen_frame_count between 0 and 30),\n  population            population_strength,\n  pollen_importation    boolean,\n\n  -- celle reali e comportamento\n  queen_cells           queen_cells_type not null default 'nessuna',\n  behavior              behavior_type,\n\n  -- patologie (multi-select)\n  pathologies           pathology[] not null default '{}',\n\n  -- varroa (opzionale)\n  varroa_count          numeric(6, 2),\n  varroa_count_method   varroa_count_method,\n\n  -- interventi e melari\n  interventions         text[] not null default '{}',\n  melari_count          smallint not null default 0\n                          check (melari_count between 0 and 10),\n\n  -- testo libero\n  notes                 text,\n\n  -- audit\n  created_at            timestamptz not null default now(),\n  updated_at            timestamptz not null default now(),\n\n  -- coerenza varroa: se c''è il valore deve esserci anche il metodo\n  check (\n    (varroa_count is null and varroa_count_method is null)\n    or\n    (varroa_count is not null and varroa_count_method is not null)\n  )\n)","comment on table public.inspections is\n  'Ispezioni di un''arnia. Record immutabile dal punto di vista '\n  'applicativo (l''utente può modificare entro un breve lasso, '\n  'ma da MVP nessuna policy DB lo impedisce).'","comment on column public.inspections.melari_count is\n  'Numero di melari presenti SUL''ARNIA al termine dell''ispezione. '\n  'Usato dal controllo trattamenti antivarroa per validare incompatibilità.'","create trigger inspections_set_timestamp\n  before update on public.inspections\n  for each row execute function public.trigger_set_timestamp()","-- =====================================================================\n-- 12. TRATTAMENTI\n-- =====================================================================\n-- Un trattamento può coinvolgere più arnie (anche di apiari diversi\n-- in teoria, ma in pratica sempre dello stesso apiario). La M:N è\n-- in treatment_hives.\n\ncreate table public.treatments (\n  id              uuid primary key default gen_random_uuid(),\n  apiary_id       uuid not null references public.apiaries(id) on delete restrict,\n  product_name    text not null,  -- es: \\"Apivar\\", \\"Api-Bioxal\\", testo libero\n  -- \\"antivarroa con esclusione melari\\": determina se l''app deve\n  -- avvisare quando le arnie hanno melari montati al momento del trattamento\n  blocks_melari   boolean not null default true,\n  start_date      date not null,\n  end_date        date,\n  dosage_notes    text,\n  cost_eur        numeric(8, 2) check (cost_eur >= 0),\n  performed_by    uuid not null references public.profiles(id),\n  notes           text,\n  created_at      timestamptz not null default now(),\n  updated_at      timestamptz not null default now(),\n  check (end_date is null or end_date >= start_date)\n)","comment on table public.treatments is\n  'Trattamenti sanitari registrati. Le arnie coinvolte sono in treatment_hives.'","create trigger treatments_set_timestamp\n  before update on public.treatments\n  for each row execute function public.trigger_set_timestamp()","-- Tabella di giunzione N:M\ncreate table public.treatment_hives (\n  treatment_id uuid not null references public.treatments(id) on delete cascade,\n  hive_id      uuid not null references public.hives(id) on delete restrict,\n  primary key (treatment_id, hive_id)\n)","-- =====================================================================\n-- 13. RACCOLTI\n-- =====================================================================\n\ncreate table public.harvests (\n  id              uuid primary key default gen_random_uuid(),\n  apiary_id       uuid not null references public.apiaries(id) on delete restrict,\n  harvested_on    date not null,\n  honey_type      text not null,\n  -- es: 'acacia','castagno','tiglio','millefiori','melata','sulla',\n  --     'agrumi','eucalipto','altro'\n  -- Tenuto come TEXT per estensibilità senza migrazioni.\n  total_kg        numeric(8, 2) not null check (total_kg > 0),\n  humidity_pct    numeric(4, 1) check (humidity_pct between 0 and 100),\n  batch_code      text,\n  notes           text,\n  recorded_by     uuid not null references public.profiles(id),\n  created_at      timestamptz not null default now(),\n  updated_at      timestamptz not null default now()\n)","create trigger harvests_set_timestamp\n  before update on public.harvests\n  for each row execute function public.trigger_set_timestamp()","-- =====================================================================\n-- 14. PROMEMORIA\n-- =====================================================================\n\ncreate table public.reminders (\n  id                 uuid primary key default gen_random_uuid(),\n  user_id            uuid not null references public.profiles(id) on delete cascade,\n  title              text not null check (length(title) between 1 and 200),\n  description        text,\n  due_at             timestamptz not null,\n  recurrence         reminder_recurrence not null default 'none',\n  scope              reminder_scope not null,\n  apiary_id          uuid references public.apiaries(id) on delete cascade,\n  hive_id            uuid references public.hives(id) on delete cascade,\n  push_enabled       boolean not null default true,\n  completed_at       timestamptz,\n  created_at         timestamptz not null default now(),\n  updated_at         timestamptz not null default now(),\n\n  -- coerenza scope <-> riferimenti\n  check (\n    (scope = 'global' and apiary_id is null and hive_id is null)\n    or\n    (scope = 'apiary' and apiary_id is not null and hive_id is null)\n    or\n    (scope = 'hive'   and hive_id is not null)\n  )\n)","comment on table public.reminders is\n  'Promemoria personali dell''utente. Il reminder annuale BDA non '\n  'sta in questa tabella ma è generato lato client se l''utente possiede '\n  'un apiario con bda_codice_aziendale valorizzato.'","create trigger reminders_set_timestamp\n  before update on public.reminders\n  for each row execute function public.trigger_set_timestamp()","-- =====================================================================\n-- 15. MEDIA (foto/video)\n-- =====================================================================\n-- Un media è agganciato a UN solo target tra: apiary, hive, inspection.\n-- Lo storage fisico è in un bucket Supabase, qui c''è solo il puntatore.\n\ncreate table public.media (\n  id              uuid primary key default gen_random_uuid(),\n  kind            media_kind not null,\n  storage_path    text not null,  -- path nel bucket Supabase\n  thumbnail_path  text,\n  caption         text,\n  apiary_id       uuid references public.apiaries(id) on delete cascade,\n  hive_id         uuid references public.hives(id) on delete cascade,\n  inspection_id   uuid references public.inspections(id) on delete cascade,\n  uploaded_by     uuid not null references public.profiles(id),\n  size_bytes      bigint check (size_bytes > 0),\n  width           integer,\n  height          integer,\n  duration_seconds integer,  -- solo per video\n  created_at      timestamptz not null default now(),\n\n  -- esattamente uno dei tre target deve essere valorizzato\n  constraint media_target_exclusive check (\n    (case when apiary_id     is not null then 1 else 0 end) +\n    (case when hive_id       is not null then 1 else 0 end) +\n    (case when inspection_id is not null then 1 else 0 end) = 1\n  )\n)","comment on table public.media is\n  'Riferimenti a foto e video. Il binario sta nel bucket Supabase Storage.'","-- =====================================================================\n-- 16. INDICI\n-- =====================================================================\n-- PK e UNIQUE creano già indici. Aggiungiamo gli accessi più frequenti.\n\ncreate index idx_apiaries_owner       on public.apiaries(owner_id) where archived_at is null","create index idx_hives_apiary         on public.hives(apiary_id) where archived_at is null","create index idx_hives_status         on public.hives(status)","create index idx_inspections_hive_at  on public.inspections(hive_id, performed_at desc)","create index idx_inspections_perf_by  on public.inspections(performed_by)","create index idx_treatments_apiary    on public.treatments(apiary_id, start_date desc)","create index idx_treatment_hives_hive on public.treatment_hives(hive_id)","create index idx_harvests_apiary      on public.harvests(apiary_id, harvested_on desc)","create index idx_reminders_user_due   on public.reminders(user_id, due_at) where completed_at is null","create index idx_reminders_apiary     on public.reminders(apiary_id) where apiary_id is not null","create index idx_reminders_hive       on public.reminders(hive_id)   where hive_id   is not null","create index idx_media_apiary         on public.media(apiary_id)     where apiary_id is not null","create index idx_media_hive           on public.media(hive_id)       where hive_id   is not null","create index idx_media_inspection     on public.media(inspection_id) where inspection_id is not null","create index idx_apiary_access_user   on public.apiary_access(user_id)","create index idx_hive_access_user     on public.hive_access(user_id)","create index idx_invites_email        on public.apiary_invites(email) where accepted_at is null","create index idx_queens_hive          on public.queens(hive_id)","-- =====================================================================\n-- 17. FUNZIONI HELPER PER RLS\n-- =====================================================================\n-- Le policy RLS dirette su apiaries/hives/access creerebbero ricorsione.\n-- Le racchiudo in funzioni SECURITY DEFINER così l''interno bypassa RLS\n-- in modo controllato (search_path bloccato a public).\n\ncreate or replace function public.user_can_read_apiary(p_apiary_id uuid)\nreturns boolean\nlanguage sql\nsecurity definer\nstable\nset search_path = public\nas $$\n  select exists (\n    select 1 from apiaries a\n    where a.id = p_apiary_id\n      and (\n        a.owner_id = auth.uid()\n        or exists (\n          select 1 from apiary_access aa\n          where aa.apiary_id = p_apiary_id and aa.user_id = auth.uid()\n        )\n        or exists (\n          select 1 from hives h\n          join hive_access ha on ha.hive_id = h.id\n          where h.apiary_id = p_apiary_id and ha.user_id = auth.uid()\n        )\n      )\n  );\n$$","create or replace function public.user_can_write_apiary(p_apiary_id uuid)\nreturns boolean\nlanguage sql\nsecurity definer\nstable\nset search_path = public\nas $$\n  select exists (\n    select 1 from apiaries a\n    where a.id = p_apiary_id\n      and (\n        a.owner_id = auth.uid()\n        or exists (\n          select 1 from apiary_access aa\n          where aa.apiary_id = p_apiary_id\n            and aa.user_id   = auth.uid()\n            and aa.role      = 'editor'\n        )\n      )\n  );\n$$","create or replace function public.user_owns_apiary(p_apiary_id uuid)\nreturns boolean\nlanguage sql\nsecurity definer\nstable\nset search_path = public\nas $$\n  select exists (\n    select 1 from apiaries a\n    where a.id = p_apiary_id and a.owner_id = auth.uid()\n  );\n$$","create or replace function public.user_can_read_hive(p_hive_id uuid)\nreturns boolean\nlanguage sql\nsecurity definer\nstable\nset search_path = public\nas $$\n  select exists (\n    select 1 from hives h\n    where h.id = p_hive_id\n      and (\n        public.user_can_read_apiary(h.apiary_id)\n        or exists (\n          select 1 from hive_access ha\n          where ha.hive_id = p_hive_id and ha.user_id = auth.uid()\n        )\n      )\n  );\n$$","create or replace function public.user_can_write_hive(p_hive_id uuid)\nreturns boolean\nlanguage sql\nsecurity definer\nstable\nset search_path = public\nas $$\n  select exists (\n    select 1 from hives h\n    where h.id = p_hive_id\n      and (\n        public.user_can_write_apiary(h.apiary_id)\n        or exists (\n          select 1 from hive_access ha\n          where ha.hive_id = p_hive_id\n            and ha.user_id  = auth.uid()\n            and ha.role     = 'editor'\n        )\n      )\n  );\n$$","-- =====================================================================\n-- 18. ABILITAZIONE RLS\n-- =====================================================================\n\nalter table public.profiles         enable row level security","alter table public.apiaries         enable row level security","alter table public.apiary_access    enable row level security","alter table public.apiary_invites   enable row level security","alter table public.hives            enable row level security","alter table public.hive_access      enable row level security","alter table public.queens           enable row level security","alter table public.inspections      enable row level security","alter table public.treatments       enable row level security","alter table public.treatment_hives  enable row level security","alter table public.harvests         enable row level security","alter table public.reminders        enable row level security","alter table public.media            enable row level security","-- =====================================================================\n-- 19. POLICY RLS\n-- =====================================================================\n\n-- ---- profiles ----\n-- Lettura: tutti i profili sono leggibili da utenti autenticati\n-- (servono per mostrare nomi nei membri condivisi, autori ispezioni, etc.).\n-- In v2 si potrebbe restringere ai soli profili che condividono almeno\n-- una risorsa con l''utente.\ncreate policy profiles_read on public.profiles\n  for select using (auth.uid() is not null)","create policy profiles_update_self on public.profiles\n  for update using (id = auth.uid()) with check (id = auth.uid())","-- ---- apiaries ----\ncreate policy apiaries_select on public.apiaries\n  for select using (public.user_can_read_apiary(id))","create policy apiaries_insert on public.apiaries\n  for insert with check (owner_id = auth.uid())","create policy apiaries_update on public.apiaries\n  for update using (public.user_can_write_apiary(id))\n              with check (public.user_can_write_apiary(id))","create policy apiaries_delete on public.apiaries\n  for delete using (public.user_owns_apiary(id))","-- ---- apiary_access ----\n-- Vede l''accesso: il diretto interessato + l''owner dell''apiario.\n-- Modifica/cancella/inserisce: solo l''owner.\ncreate policy apiary_access_select on public.apiary_access\n  for select using (\n    user_id = auth.uid() or public.user_owns_apiary(apiary_id)\n  )","create policy apiary_access_insert on public.apiary_access\n  for insert with check (public.user_owns_apiary(apiary_id))","create policy apiary_access_update on public.apiary_access\n  for update using (public.user_owns_apiary(apiary_id))\n              with check (public.user_owns_apiary(apiary_id))","create policy apiary_access_delete on public.apiary_access\n  for delete using (public.user_owns_apiary(apiary_id))","-- ---- apiary_invites ----\ncreate policy invites_select on public.apiary_invites\n  for select using (public.user_owns_apiary(apiary_id))","create policy invites_insert on public.apiary_invites\n  for insert with check (public.user_owns_apiary(apiary_id))","create policy invites_delete on public.apiary_invites\n  for delete using (public.user_owns_apiary(apiary_id))","-- ---- hives ----\ncreate policy hives_select on public.hives\n  for select using (public.user_can_read_hive(id))","create policy hives_insert on public.hives\n  for insert with check (public.user_can_write_apiary(apiary_id))","create policy hives_update on public.hives\n  for update using (public.user_can_write_hive(id))\n              with check (public.user_can_write_hive(id))","create policy hives_delete on public.hives\n  for delete using (public.user_owns_apiary(apiary_id))","-- ---- hive_access ----\ncreate policy hive_access_select on public.hive_access\n  for select using (\n    user_id = auth.uid()\n    or exists (\n      select 1 from hives h\n      where h.id = hive_access.hive_id\n        and public.user_owns_apiary(h.apiary_id)\n    )\n  )","create policy hive_access_insert on public.hive_access\n  for insert with check (\n    exists (\n      select 1 from hives h\n      where h.id = hive_access.hive_id\n        and public.user_owns_apiary(h.apiary_id)\n    )\n  )","create policy hive_access_delete on public.hive_access\n  for delete using (\n    exists (\n      select 1 from hives h\n      where h.id = hive_access.hive_id\n        and public.user_owns_apiary(h.apiary_id)\n    )\n  )","-- ---- queens ----\ncreate policy queens_select on public.queens\n  for select using (public.user_can_read_hive(hive_id))","create policy queens_insert on public.queens\n  for insert with check (public.user_can_write_hive(hive_id))","create policy queens_update on public.queens\n  for update using (public.user_can_write_hive(hive_id))\n              with check (public.user_can_write_hive(hive_id))","create policy queens_delete on public.queens\n  for delete using (public.user_can_write_hive(hive_id))","-- ---- inspections ----\ncreate policy inspections_select on public.inspections\n  for select using (public.user_can_read_hive(hive_id))","create policy inspections_insert on public.inspections\n  for insert with check (\n    public.user_can_write_hive(hive_id)\n    and performed_by = auth.uid()\n  )","-- Update consentita solo all''autore, per mantenere integrità dello storico.\ncreate policy inspections_update on public.inspections\n  for update using (\n    performed_by = auth.uid()\n    and public.user_can_write_hive(hive_id)\n  ) with check (\n    performed_by = auth.uid()\n    and public.user_can_write_hive(hive_id)\n  )","create policy inspections_delete on public.inspections\n  for delete using (\n    performed_by = auth.uid()\n    and public.user_can_write_hive(hive_id)\n  )","-- ---- treatments ----\ncreate policy treatments_select on public.treatments\n  for select using (public.user_can_read_apiary(apiary_id))","create policy treatments_insert on public.treatments\n  for insert with check (\n    public.user_can_write_apiary(apiary_id)\n    and performed_by = auth.uid()\n  )","create policy treatments_update on public.treatments\n  for update using (\n    performed_by = auth.uid()\n    and public.user_can_write_apiary(apiary_id)\n  ) with check (\n    performed_by = auth.uid()\n    and public.user_can_write_apiary(apiary_id)\n  )","create policy treatments_delete on public.treatments\n  for delete using (\n    performed_by = auth.uid()\n    and public.user_can_write_apiary(apiary_id)\n  )","-- ---- treatment_hives ----\ncreate policy treatment_hives_select on public.treatment_hives\n  for select using (\n    exists (\n      select 1 from treatments t\n      where t.id = treatment_hives.treatment_id\n        and public.user_can_read_apiary(t.apiary_id)\n    )\n  )","create policy treatment_hives_insert on public.treatment_hives\n  for insert with check (\n    exists (\n      select 1 from treatments t\n      where t.id = treatment_hives.treatment_id\n        and public.user_can_write_apiary(t.apiary_id)\n    )\n    and public.user_can_write_hive(hive_id)\n  )","create policy treatment_hives_delete on public.treatment_hives\n  for delete using (\n    exists (\n      select 1 from treatments t\n      where t.id = treatment_hives.treatment_id\n        and t.performed_by = auth.uid()\n    )\n  )","-- ---- harvests ----\ncreate policy harvests_select on public.harvests\n  for select using (public.user_can_read_apiary(apiary_id))","create policy harvests_insert on public.harvests\n  for insert with check (\n    public.user_can_write_apiary(apiary_id)\n    and recorded_by = auth.uid()\n  )","create policy harvests_update on public.harvests\n  for update using (\n    recorded_by = auth.uid()\n    and public.user_can_write_apiary(apiary_id)\n  ) with check (\n    recorded_by = auth.uid()\n    and public.user_can_write_apiary(apiary_id)\n  )","create policy harvests_delete on public.harvests\n  for delete using (\n    recorded_by = auth.uid()\n    and public.user_can_write_apiary(apiary_id)\n  )","-- ---- reminders ----\n-- Personali: ogni utente vede e gestisce solo i propri.\ncreate policy reminders_all on public.reminders\n  for all using (user_id = auth.uid())\n          with check (user_id = auth.uid())","-- ---- media ----\ncreate policy media_select on public.media\n  for select using (\n    case\n      when apiary_id     is not null then public.user_can_read_apiary(apiary_id)\n      when hive_id       is not null then public.user_can_read_hive(hive_id)\n      when inspection_id is not null then exists (\n        select 1 from inspections i\n        where i.id = media.inspection_id\n          and public.user_can_read_hive(i.hive_id)\n      )\n      else false\n    end\n  )","create policy media_insert on public.media\n  for insert with check (\n    uploaded_by = auth.uid()\n    and case\n      when apiary_id     is not null then public.user_can_write_apiary(apiary_id)\n      when hive_id       is not null then public.user_can_write_hive(hive_id)\n      when inspection_id is not null then exists (\n        select 1 from inspections i\n        where i.id = media.inspection_id\n          and public.user_can_write_hive(i.hive_id)\n      )\n      else false\n    end\n  )","create policy media_delete on public.media\n  for delete using (\n    uploaded_by = auth.uid()\n    or case\n      when apiary_id     is not null then public.user_owns_apiary(apiary_id)\n      when hive_id       is not null then exists (\n        select 1 from hives h\n        where h.id = media.hive_id\n          and public.user_owns_apiary(h.apiary_id)\n      )\n      when inspection_id is not null then exists (\n        select 1 from inspections i\n        join hives h on h.id = i.hive_id\n        where i.id = media.inspection_id\n          and public.user_owns_apiary(h.apiary_id)\n      )\n      else false\n    end\n  )","-- =====================================================================\n-- 20. STORAGE BUCKET (eseguire dopo dalla dashboard Supabase)\n-- =====================================================================\n-- I bucket si creano dalla dashboard Supabase (Storage). Indicazioni:\n--\n--   1) Bucket name:        apidiario-media\n--   2) Public:             NO (privato, accessi solo via signed URL)\n--   3) File size limit:    20 MB per file\n--   4) Allowed MIME types: image/jpeg, image/png, image/heic,\n--                          image/webp, video/mp4, video/quicktime\n--\n-- Le policy del bucket vanno definite a parte; un buon set iniziale è:\n--\n--   - SELECT/INSERT consentito al solo proprietario del file (owner = auth.uid())\n--   - DELETE consentito al proprietario o all'owner della risorsa associata\n--\n-- Una validazione più stringente (allineata alle RLS della tabella media)\n-- la facciamo successivamente con una funzione di hook lato client che\n-- verifica le permission prima di chiedere l''upload URL.\n\n\n-- =====================================================================\n-- FINE SCHEMA\n-- ====================================================================="}	initial_schema
20260503000000	{"-- Allow NULL for queen_cells and pathologies so Express mode inspections\n-- can record \\"not observed\\" (NULL) vs \\"none observed\\" (default value).\nalter table inspections\n  alter column queen_cells drop not null,\n  alter column queen_cells drop default,\n  alter column pathologies drop not null,\n  alter column pathologies drop default"}	inspections_nullable_express_fields
20260506000000	{"-- Add main_photo_path to apiaries table.\n-- Stores the Storage path (bucket: apidiario-media, path: apiaries/{id}/main.{ext}).\n-- URL resolution happens client-side via createSignedUrl.\n\nalter table public.apiaries\n  add column if not exists main_photo_path text"}	add_apiary_main_photo
20260507000000	{"-- SECURITY DEFINER helper: check storage path ownership without triggering apiaries RLS.\n-- Path convention: apiaries/{apiary_uuid}/main.{ext}\nCREATE OR REPLACE FUNCTION public.storage_owns_apiary_media(object_name text)\nRETURNS boolean\nLANGUAGE plpgsql\nSECURITY DEFINER\nSTABLE\nSET search_path = public\nAS $$\nBEGIN\n  RETURN (\n    auth.uid() IS NOT NULL\n    AND EXISTS (\n      SELECT 1 FROM apiaries\n       WHERE id::text = (string_to_array(object_name, '/'))[2]\n         AND owner_id = auth.uid()\n    )\n  );\nEND;\n$$","DROP POLICY IF EXISTS \\"owner read apiary media\\"   ON storage.objects","DROP POLICY IF EXISTS \\"owner insert apiary media\\" ON storage.objects","DROP POLICY IF EXISTS \\"owner update apiary media\\" ON storage.objects","DROP POLICY IF EXISTS \\"owner delete apiary media\\" ON storage.objects","CREATE POLICY \\"owner read apiary media\\"\n  ON storage.objects FOR SELECT\n  USING (bucket_id = 'apidiario-media' AND public.storage_owns_apiary_media(name))","CREATE POLICY \\"owner insert apiary media\\"\n  ON storage.objects FOR INSERT\n  WITH CHECK (bucket_id = 'apidiario-media' AND public.storage_owns_apiary_media(name))","CREATE POLICY \\"owner update apiary media\\"\n  ON storage.objects FOR UPDATE\n  USING (bucket_id = 'apidiario-media' AND public.storage_owns_apiary_media(name))","CREATE POLICY \\"owner delete apiary media\\"\n  ON storage.objects FOR DELETE\n  USING (bucket_id = 'apidiario-media' AND public.storage_owns_apiary_media(name))"}	storage_rls_fix
20260507000001	{"-- Atomic RPC: inserts hive + its first queen in a single transaction.\n-- SECURITY DEFINER so we can bypass RLS for both tables; ownership\n-- is verified explicitly before any INSERT.\nCREATE OR REPLACE FUNCTION public.create_hive_with_queen(\n  p_id               uuid,\n  p_apiary_id        uuid,\n  p_identifier       text,\n  p_hive_type        public.hive_type,\n  p_bee_race         public.bee_race,\n  p_installed_on     date,\n  p_origin_notes     text,\n  p_nido_frame_count smallint,\n  p_notes            text\n)\nRETURNS void\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nBEGIN\n  IF NOT EXISTS (\n    SELECT 1 FROM apiaries WHERE id = p_apiary_id AND owner_id = auth.uid()\n  ) THEN\n    RAISE EXCEPTION 'unauthorized';\n  END IF;\n\n  INSERT INTO hives (\n    id, apiary_id, identifier, hive_type, bee_race,\n    installed_on, origin_notes, nido_frame_count, notes\n  ) VALUES (\n    p_id, p_apiary_id, p_identifier, p_hive_type, p_bee_race,\n    p_installed_on, p_origin_notes, p_nido_frame_count, p_notes\n  );\n\n  INSERT INTO queens (hive_id, marking_color, origin, start_date)\n  VALUES (p_id, 'non_marcata', 'sconosciuta', COALESCE(p_installed_on, CURRENT_DATE));\nEND;\n$$"}	create_hive_with_queen
20260507000003	{"alter table public.hives\n  add column has_apiscampo    boolean not null default false,\n  add column has_propolis_net boolean not null default false"}	hive_accessories
20260507000004	{"alter table public.hives\n  add column melari_count smallint not null default 0\n    check (melari_count between 0 and 10)"}	hive_melari_count
20260507000005	{"alter table public.hives\n  add column has_pollen_trap boolean not null default false"}	hive_pollen_trap
20260507232111	{"create extension if not exists pgtap with schema extensions"}	enable_pgtap
20260507235017	{"-- =====================================================================\n-- Drop hive_access e apiary_invites\n-- =====================================================================\n-- Decisione di prodotto: la condivisione è solo a livello di apiario.\n-- Non si condividono singole arnie. Inoltre gli inviti pending a email\n-- non registrate non sono più previsti.\n--\n -- Strategy: CREATE OR REPLACE FUNCTION per rimuovere i riferimenti a\n-- hive_access dalle 3 funzioni helper (firma invariata). Le policy\n-- esistenti continuano a funzionare perché le funzioni hanno stesso\n-- nome e stessa firma. Poi DROP TABLE CASCADE per eliminare le tabelle\n-- e le loro policy RLS.\n-- =====================================================================\n\n-- 1. Riscrivi user_can_read_apiary senza JOIN hive_access\ncreate or replace function public.user_can_read_apiary(p_apiary_id uuid)\nreturns boolean\nlanguage sql\nsecurity definer\nstable\nset search_path = public\nas $$\n  select exists (\n    select 1 from apiaries a\n    where a.id = p_apiary_id\n      and (\n        a.owner_id = auth.uid()\n        or exists (\n          select 1 from apiary_access aa\n          where aa.apiary_id = p_apiary_id and aa.user_id = auth.uid()\n        )\n      )\n  );\n$$","-- 2. Riscrivi user_can_read_hive senza SELECT da hive_access\ncreate or replace function public.user_can_read_hive(p_hive_id uuid)\nreturns boolean\nlanguage sql\nsecurity definer\nstable\nset search_path = public\nas $$\n  select exists (\n    select 1 from hives h\n    where h.id = p_hive_id\n      and public.user_can_read_apiary(h.apiary_id)\n  );\n$$","-- 3. Riscrivi user_can_write_hive senza SELECT da hive_access\ncreate or replace function public.user_can_write_hive(p_hive_id uuid)\nreturns boolean\nlanguage sql\nsecurity definer\nstable\nset search_path = public\nas $$\n  select exists (\n    select 1 from hives h\n    where h.id = p_hive_id\n      and public.user_can_write_apiary(h.apiary_id)\n  );\n$$","-- 4. Drop tabelle (cascade elimina anche policy RLS su di esse)\ndrop table if exists public.hive_access cascade","drop table if exists public.apiary_invites cascade"}	drop_hive_access_and_invites
20260508000000	{"-- =====================================================================\n-- Migrazione: tabella app_admins + helper RLS\n-- =====================================================================\n-- Crea la tabella degli amministratori applicativi. Solo chi compare\n-- qui puo' invitare nuovi utenti e accedere alla pagina /admin/users.\n-- =====================================================================\n-- BOOTSTRAP (da eseguire a mano dopo la migrazione via SQL editor):\n--\n--   insert into public.app_admins (user_id, created_by)\n--   values ('<your-user-id>', '<your-user-id>');\n--\n-- Sostituisci <your-user-id> con il tuo UUID da auth.users.\n-- Il primo admin si auto-promuove (created_by = se stesso).\n-- =====================================================================\n\n\n-- ---------------------------------------------------------------------\n-- Tabella amministratori\n-- ---------------------------------------------------------------------\ncreate table public.app_admins (\n  user_id    uuid primary key references auth.users(id) on delete cascade,\n  created_by uuid not null references auth.users(id),\n  created_at timestamptz not null default now()\n)","comment on table public.app_admins is\n  'Amministratori applicativi. RLS: solo admin legge/scrive.'","comment on column public.app_admins.created_by is\n  'Chi ha promosso questo admin. Il bootstrap si auto-referenzia.'","comment on column public.app_admins.created_at is\n  'Data di promozione ad admin.'","-- ---------------------------------------------------------------------\n-- Helper SECURITY DEFINER: verifica se l'utente corrente e' admin\n-- ---------------------------------------------------------------------\n-- Usata dalle policy RLS. SECURITY DEFINER con search_path bloccato\n-- per evitare ricorsione.\n-- ---------------------------------------------------------------------\ncreate or replace function public.is_app_admin()\nreturns boolean\nlanguage sql\nsecurity definer\nstable\nset search_path = public\nas $$\n  select exists (\n    select 1 from public.app_admins where user_id = auth.uid()\n  );\n$$","comment on function public.is_app_admin() is\n  'RLS helper: true se auth.uid() compare in app_admins.'","-- ---------------------------------------------------------------------\n-- RLS\n-- ---------------------------------------------------------------------\nalter table public.app_admins enable row level security","-- SELECT: solo admin vede la tabella (altri vedono 0 righe)\ncreate policy app_admins_select on public.app_admins\n  for select using (public.is_app_admin())","-- INSERT: solo admin puo' promuovere altri\ncreate policy app_admins_insert on public.app_admins\n  for insert with check (public.is_app_admin())","-- DELETE: solo admin puo' rimuovere admin (demote)\n-- Nota: con questa policy un admin puo' rimuovere altri admin,\n-- incluso se stesso (self-demotion). La protezione e' lato Edge Function.\ncreate policy app_admins_delete on public.app_admins\n  for delete using (public.is_app_admin())"}	app_admins
20260508000001	{"-- Phenology & GDD-based bloom prediction\n\n-- ── Species reference table ────────────────────────────────────\n\nCREATE TABLE phenology_species (\n  id text PRIMARY KEY,\n  common_name_it text NOT NULL,\n  scientific_name text NOT NULL,\n  gdd_bloom_start numeric NOT NULL,\n  gdd_bloom_peak numeric NOT NULL,\n  gdd_bloom_end numeric NOT NULL,\n  bloom_period_text text,\n  honey_relevance int CHECK (honey_relevance BETWEEN 1 AND 5),\n  produces_honey boolean DEFAULT true,\n  produces_pollen boolean DEFAULT true,\n  notes_it text\n)","INSERT INTO phenology_species VALUES\n('mandorlo', 'Mandorlo', 'Prunus dulcis', 150, 200, 280, 'feb-mar', 3, false, true, 'Importante per polline precoce'),\n('salice', 'Salice', 'Salix spp.', 180, 240, 320, 'marzo', 4, true, true, 'Polline e nettare di inizio stagione'),\n('pesco', 'Pesco', 'Prunus persica', 240, 290, 370, 'marzo', 3, true, true, NULL),\n('ciliegio', 'Ciliegio', 'Prunus avium', 280, 340, 420, 'marzo-aprile', 4, true, true, NULL),\n('tarassaco', 'Tarassaco', 'Taraxacum officinale', 250, 350, 500, 'aprile-maggio', 4, true, true, 'Fioritura prolungata'),\n('erica_arborea', 'Erica arborea', 'Erica arborea', 200, 280, 400, 'marzo-aprile', 4, true, true, 'Tipica zone costiere e maremmane'),\n('colza', 'Colza', 'Brassica napus', 350, 450, 600, 'aprile', 4, true, true, NULL),\n('acero', 'Acero', 'Acer spp.', 320, 400, 520, 'aprile', 3, true, true, NULL),\n('biancospino', 'Biancospino', 'Crataegus monogyna', 420, 500, 620, 'aprile-maggio', 3, true, true, NULL),\n('robinia', 'Robinia (acacia)', 'Robinia pseudoacacia', 540, 640, 780, 'maggio', 5, true, true, 'Miele monoflora pregiato'),\n('sulla', 'Sulla', 'Hedysarum coronarium', 580, 700, 880, 'maggio', 5, true, true, 'Centro-sud Italia'),\n('ailanto', 'Ailanto', 'Ailanthus altissima', 700, 820, 980, 'giugno', 3, true, true, 'Specie invasiva ma melifera'),\n('tiglio_cordata', 'Tiglio selvatico', 'Tilia cordata', 720, 850, 1020, 'giugno', 5, true, true, NULL),\n('tiglio_platyphyllos', 'Tiglio nostrano', 'Tilia platyphyllos', 680, 800, 970, 'giugno', 5, true, true, NULL),\n('castagno', 'Castagno', 'Castanea sativa', 950, 1100, 1300, 'giugno-luglio', 5, true, true, 'Miele tipico aree montane'),\n('rovo', 'Rovo', 'Rubus spp.', 700, 900, 1200, 'giugno-luglio', 4, true, true, 'Spesso usato in millefiori'),\n('lavanda', 'Lavanda', 'Lavandula angustifolia', 950, 1150, 1450, 'giugno-luglio', 4, true, true, NULL),\n('erba_medica', 'Erba medica', 'Medicago sativa', 850, 1050, 1350, 'giugno-settembre', 4, true, true, 'Fioritura multipla post-sfalcio'),\n('girasole', 'Girasole', 'Helianthus annuus', 1100, 1300, 1550, 'luglio', 5, true, true, 'Dipende da data semina'),\n('eucalipto', 'Eucalipto', 'Eucalyptus spp.', 1200, 1450, 1750, 'luglio-agosto', 4, true, true, 'Soprattutto centro-sud'),\n('metcalfa', 'Melata di metcalfa', 'Metcalfa pruinosa', 1400, 1600, 1900, 'luglio-agosto', 4, true, false, 'Produzione di melata da insetto'),\n('edera', 'Edera', 'Hedera helix', 2400, 2600, 2850, 'settembre-ottobre', 4, true, true, 'Apporto pre-invernale'),\n('corbezzolo', 'Corbezzolo', 'Arbutus unedo', 2600, 2850, 3100, 'ottobre-novembre', 5, true, true, 'Miele amaro, ultimo della stagione')","CREATE INDEX idx_species_bloom_start ON phenology_species(gdd_bloom_start)","-- ── Daily weather per apiary ───────────────────────────────────\n\nCREATE TABLE daily_weather (\n  apiary_id uuid NOT NULL REFERENCES apiaries(id) ON DELETE CASCADE,\n  date date NOT NULL,\n  tmin numeric NOT NULL,\n  tmax numeric NOT NULL,\n  source text NOT NULL DEFAULT 'open-meteo',\n  fetched_at timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (apiary_id, date)\n)","CREATE INDEX idx_weather_apiary_date ON daily_weather(apiary_id, date DESC)","-- ── Materialized view: cumulative GDD ──────────────────────────\n\nCREATE MATERIALIZED VIEW apiary_gdd_cumulative AS\nSELECT\n  apiary_id,\n  date,\n  EXTRACT(YEAR FROM date)::int AS year,\n  GREATEST(0, (LEAST(tmax, 30) + LEAST(tmin, 30)) / 2.0 - 5.0) AS gdd_daily,\n  SUM(GREATEST(0, (LEAST(tmax, 30) + LEAST(tmin, 30)) / 2.0 - 5.0))\n    OVER (\n      PARTITION BY apiary_id, EXTRACT(YEAR FROM date)\n      ORDER BY date\n    ) AS gdd_cumulative\nFROM daily_weather","CREATE UNIQUE INDEX idx_gdd_cum ON apiary_gdd_cumulative(apiary_id, date)","-- ── RLS: users can read weather for their own apiaries ─────────\n\nALTER TABLE daily_weather ENABLE ROW LEVEL SECURITY","DROP POLICY IF EXISTS user_can_read_own_weather ON daily_weather","CREATE POLICY user_can_read_own_weather ON daily_weather\n  FOR SELECT\n  USING (\n    EXISTS (\n      SELECT 1 FROM apiaries\n      WHERE apiaries.id = daily_weather.apiary_id\n        AND apiaries.owner_id = (SELECT auth.uid())\n    )\n  )","-- ── Refresh function ───────────────────────────────────────────\n\nCREATE OR REPLACE FUNCTION refresh_gdd_view()\nRETURNS void\nLANGUAGE sql\nSECURITY DEFINER\nAS $$\n  REFRESH MATERIALIZED VIEW CONCURRENTLY apiary_gdd_cumulative;\n$$"}	phenology
20260508000002	{"-- Drop unused weather tables created in phenology migration.\n-- Weather data fetched directly from Open-Meteo in the browser.\n\nDROP MATERIALIZED VIEW IF EXISTS apiary_gdd_cumulative CASCADE","DROP TABLE IF EXISTS daily_weather CASCADE","DROP FUNCTION IF EXISTS refresh_gdd_view()"}	drop_unused_weather
20260509075256	{"ALTER TABLE inspections DROP COLUMN IF EXISTS melari_count"}	drop_melari_count_from_inspections
20260509000001	{"-- Fix storage RLS: estendi da owner-only a apiary_access (editor/reader)\n-- Path convention: apiaries/{apiary_uuid}/main.{ext}\n\n-- 1. Helper: estrai apiary_id dal path\nCREATE OR REPLACE FUNCTION public.storage_get_apiary_id(object_name text)\nRETURNS uuid\nLANGUAGE sql\nIMMUTABLE\nSET search_path = public\nAS $$\n  SELECT (string_to_array(object_name, '/'))[2]::uuid;\n$$","-- 2. Helper SELECT: owner O qualsiasi utente con read access all'apiario\nCREATE OR REPLACE FUNCTION public.storage_can_read_apiary_media(object_name text)\nRETURNS boolean\nLANGUAGE sql\nSECURITY DEFINER\nSTABLE\nSET search_path = public\nAS $$\n  SELECT auth.uid() IS NOT NULL\n    AND public.user_can_read_apiary(public.storage_get_apiary_id(object_name));\n$$","-- 3. Helper INSERT/UPDATE: owner O utente con write access all'apiario\nCREATE OR REPLACE FUNCTION public.storage_can_write_apiary_media(object_name text)\nRETURNS boolean\nLANGUAGE sql\nSECURITY DEFINER\nSTABLE\nSET search_path = public\nAS $$\n  SELECT auth.uid() IS NOT NULL\n    AND public.user_can_write_apiary(public.storage_get_apiary_id(object_name));\n$$","-- 4. Helper DELETE: owner apiario O uploader del file\nCREATE OR REPLACE FUNCTION public.storage_can_delete_apiary_media(object_name text)\nRETURNS boolean\nLANGUAGE sql\nSECURITY DEFINER\nSTABLE\nSET search_path = public\nAS $$\n  SELECT auth.uid() IS NOT NULL\n    AND (\n      public.user_owns_apiary(public.storage_get_apiary_id(object_name))\n      OR EXISTS (\n        SELECT 1 FROM storage.objects\n        WHERE name = object_name\n          AND bucket_id = 'apidiario-media'\n          AND owner = auth.uid()\n      )\n    );\n$$","-- 5. Sostituisci policy storage\nDROP POLICY IF EXISTS \\"owner read apiary media\\"   ON storage.objects","DROP POLICY IF EXISTS \\"owner insert apiary media\\" ON storage.objects","DROP POLICY IF EXISTS \\"owner update apiary media\\" ON storage.objects","DROP POLICY IF EXISTS \\"owner delete apiary media\\" ON storage.objects","CREATE POLICY \\"read apiary media\\"\n  ON storage.objects FOR SELECT\n  USING (bucket_id = 'apidiario-media' AND public.storage_can_read_apiary_media(name))","CREATE POLICY \\"insert apiary media\\"\n  ON storage.objects FOR INSERT\n  WITH CHECK (bucket_id = 'apidiario-media' AND public.storage_can_write_apiary_media(name))","CREATE POLICY \\"update apiary media\\"\n  ON storage.objects FOR UPDATE\n  USING (bucket_id = 'apidiario-media' AND public.storage_can_write_apiary_media(name))","CREATE POLICY \\"delete apiary media\\"\n  ON storage.objects FOR DELETE\n  USING (bucket_id = 'apidiario-media' AND public.storage_can_delete_apiary_media(name))","-- 6. Rimuovi vecchia funzione (non piu' usata)\nDROP FUNCTION IF EXISTS public.storage_owns_apiary_media(text)"}	fix_storage_rls
20260509200000	{"-- Voice notes for inspections\n-- Each inspection can have multiple voice recordings.\n\nCREATE TABLE IF NOT EXISTS inspection_voice_notes (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  inspection_id uuid NOT NULL REFERENCES inspections(id) ON DELETE CASCADE,\n  storage_path text NOT NULL,\n  duration_seconds numeric(6,1) NOT NULL,\n  created_at timestamptz NOT NULL DEFAULT now()\n)","CREATE INDEX idx_voice_notes_inspection ON inspection_voice_notes(inspection_id)","ALTER TABLE inspection_voice_notes ENABLE ROW LEVEL SECURITY","CREATE POLICY voice_notes_select ON inspection_voice_notes FOR SELECT\n  USING (EXISTS (\n    SELECT 1 FROM inspections i WHERE i.id = inspection_voice_notes.inspection_id\n    AND public.user_can_read_hive(i.hive_id)\n  ))","CREATE POLICY voice_notes_insert ON inspection_voice_notes FOR INSERT\n  WITH CHECK (EXISTS (\n    SELECT 1 FROM inspections i WHERE i.id = inspection_voice_notes.inspection_id\n    AND public.user_can_write_hive(i.hive_id)\n  ))","CREATE POLICY voice_notes_delete ON inspection_voice_notes FOR DELETE\n  USING (EXISTS (\n    SELECT 1 FROM inspections i WHERE i.id = inspection_voice_notes.inspection_id\n    AND public.user_can_write_hive(i.hive_id)\n  ))"}	inspection_voice_notes
20260510000000	{"ALTER TABLE public.treatments\nADD COLUMN applies_to_all_hives boolean NOT NULL DEFAULT false","COMMENT ON COLUMN public.treatments.applies_to_all_hives IS\n  'Quando true, il trattamento si applica a tutte le arnie attive dell''apiario. Non vengono usate righe in treatment_hives.'"}	treatments_add_flag
20260510000002	{"create table activity_log (\n  id uuid not null default gen_random_uuid(),\n  user_id uuid not null references profiles(id),\n  action text not null,\n  entity_type text not null,\n  entity_id uuid,\n  description text not null,\n  created_at timestamptz not null default now(),\n\n  constraint activity_log_pkey primary key (id)\n)","alter table activity_log enable row level security","create policy \\"admins can read all logs\\"\n  on activity_log\n  for select\n  using (is_app_admin())","create policy \\"service can insert logs\\"\n  on activity_log\n  for insert\n  with check (true)","create index activity_log_created_at_idx on activity_log (created_at desc)"}	activity_log
