s text)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nBEGIN\n  IF NOT EXISTS (\n    SELECT 1 FROM apiaries WHERE id = p_apiary_id AND owner_id = auth.uid()\n  ) THEN\n    RAISE EXCEPTION 'unauthorized';\n  END IF;\n\n  INSERT INTO hives (\n    id, apiary_id, identifier, hive_type, bee_race,\n    installed_on, origin_notes, nido_frame_count, notes\n  ) VALUES (\n    p_id, p_apiary_id, p_identifier, p_hive_type, p_bee_race,\n    p_installed_on, p_origin_notes, p_nido_frame_count, p_notes\n  );\n\n  INSERT INTO queens (hive_id, marking_color, origin, start_date)\n  VALUES (p_id, 'non_marcata', 'sconosciuta', COALESCE(p_installed_on, CURRENT_DATE));\nEND;\n$function$","create policy \\"admins can read all logs\\"\n  on \\"public\\".\\"activity_log\\"\n  as permissive\n  for select\n  to public\nusing (public.is_app_admin())","create policy \\"apiaries_delete\\"\n  on \\"public\\".\\"apiaries\\"\n  as permissive\n  for delete\n  to public\nusing (public.user_owns_apiary(id))","create policy \\"apiaries_select\\"\n  on \\"public\\".\\"apiaries\\"\n  as permissive\n  for select\n  to public\nusing (public.user_can_read_apiary(id))","create policy \\"apiaries_update\\"\n  on \\"public\\".\\"apiaries\\"\n  as permissive\n  for update\n  to public\nusing (public.user_can_write_apiary(id))\nwith check (public.user_can_write_apiary(id))","create policy \\"apiary_access_delete\\"\n  on \\"public\\".\\"apiary_access\\"\n  as permissive\n  for delete\n  to public\nusing (public.user_owns_apiary(apiary_id))","create policy \\"apiary_access_insert\\"\n  on \\"public\\".\\"apiary_access\\"\n  as permissive\n  for insert\n  to public\nwith check (public.user_owns_apiary(apiary_id))","create policy \\"apiary_access_select\\"\n  on \\"public\\".\\"apiary_access\\"\n  as permissive\n  for select\n  to public\nusing (((user_id = auth.uid()) OR public.user_owns_apiary(apiary_id)))","create policy \\"apiary_access_update\\"\n  on \\"publi