\"\n  as permissive\n  for update\n  to public\nusing (public.user_can_write_hive(id))\nwith check (public.user_can_write_hive(id))","create policy \\"voice_notes_delete\\"\n  on \\"public\\".\\"inspection_voice_notes\\"\n  as permissive\n  for delete\n  to public\nusing ((EXISTS ( SELECT 1\n   FROM public.inspections i\n  WHERE ((i.id = inspection_voice_notes.inspection_id) AND public.user_can_write_hive(i.hive_id)))))","create policy \\"voice_notes_insert\\"\n  on \\"public\\".\\"inspection_voice_notes\\"\n  as permissive\n  for insert\n  to public\nwith check ((EXISTS ( SELECT 1\n   FROM public.inspections i\n  WHERE ((i.id = inspection_voice_notes.inspection_id) AND public.user_can_write_hive(i.hive_id)))))","create policy \\"voice_notes_select\\"\n  on \\"public\\".\\"inspection_voice_notes\\"\n  as permissive\n  for select\n  to public\nusing ((EXISTS ( SELECT 1\n   FROM public.inspections i\n  WHERE ((i.id = inspection_voice_notes.inspection_id) AND public.user_can_read_hive(i.hive_id)))))","create policy \\"inspections_delete\\"\n  on \\"public\\".\\"inspections\\"\n  as permissive\n  for delete\n  to public\nusing (((performed_by = auth.uid()) AND public.user_can_write_hive(hive_id)))","create policy \\"inspections_insert\\"\n  on \\"public\\".\\"inspections\\"\n  as permissive\n  for insert\n  to public\nwith check ((public.user_can_write_hive(hive_id) AND (performed_by = auth.uid())))","create policy \\"inspections_select\\"\n  on \\"public\\".\\"inspections\\"\n  as permissive\n  for select\n  to public\nusing (public.user_can_read_hive(hive_id))","create policy \\"inspections_update\\"\n  on \\"public\\".\\"inspections\\"\n  as permissive\n  for update\n  to public\nusing (((performed_by = auth.uid()) AND public.user_can_write_hive(hive_id)))\nwith check (((performed_by = auth.uid()) AND public.user_can_write_hive(hive_id)))","create policy \\"media_delete\\"\n  on \\"public\\".\\"media\\"\n  as permissive\n  for delete\n  to public\nusing (((uploaded_by = auth.uid()) OR\nCASE\n    WHEN (apiary_id IS NOT NULL) THEN public.user_owns_apiary(apiary_id)\n    WHEN (hive_id IS NOT NULL) THEN (EXISTS ( SELECT 1\n       FROM public.hives h\n      WHERE ((h.id = media.hive_id) AND public.user_owns_apiary(h.apiary_id))))\n    WHEN (inspection_id IS NOT NULL) THEN (EXISTS ( SELECT 1\n       FROM (public.inspections i\n         JOIN public.hives h ON ((h.id = i.hive_id)))\n      WHERE ((i.id = media.inspection_id) AND public.user_owns_apiary(h.apiary_id))))\n    ELSE false\nEND))","create policy \\"media_insert\\"\n  on \\"public\\".\\"media\\"\n  as permissive\n  for insert\n  to public\nwith check (((uploaded_by = auth.uid()) AND\nCASE\n    WHEN (apiary_id IS NOT NULL) THEN public.user_can_write_apiary(apiary_id)\n    WHEN (hive_id IS NOT NULL) THEN public.user_can_write_hive(hive_id)\n    WHEN (inspection_id IS NOT NULL) THEN (EXISTS ( SELECT 1\n       FROM public.inspections i\n      WHERE ((i.id = media.inspection_id) AND public.user_can_write_hive(i.hive_id))))\n    ELSE false\nEND))","create policy \\"media_select\\"\n  on \\"public\\".\\"media\\"\n  as permissive\n  for select\n  to public\nusing (\nCASE\n    WHEN (apiary_id IS NOT NULL) THEN public.user_can_read_apiary(apiary_id)\n    WHEN (hive_id IS NOT NULL) THEN public.user_can_read_hive(hive_id)\n    WHEN (inspection_id IS NOT NULL) THEN (EXISTS ( SELECT 1\n       FROM public.inspections i\n      WHERE ((i.id = media.inspection_id) AND public.user_can_read_hive(i.hive_id))))\n    ELSE false\nEND)","create policy \\"queens_delete\\"\n  on \\"public\\".\\"queens\\"\n  as permissive\n  for delete\n  to public\nusing (public.user_can_write_hive(hive_id))","create policy \\"queens_insert\\"\n  on \\"public\\".\\"queens\\"\n  as permissive\n  for insert\n  to public\nwith check (public.user_can_write_hive(hive_id))","create policy \\"queens_select\\"\n  on \\"public\\".\\"queens\\"\n  as permissive\n  for select\n  to public\nusing (public.user_can_read_hive(hive_id))","create policy \\"queens_update\\"\n  on \\"public\\".\\"queens\\"\n  as permissive\n  for update\n  to public\nusing (public.user_can_write_hive(hive_id))\nwith check (public.user_can_write_hive(hive_id))","create policy \\"treatment_hives_delete\\"\n  on \\"public\\".\\"treatment_hives\\"\n  as permissive\n  for delete\n  to public\nusing ((EXISTS ( SELECT 1\n   FROM public.treatments t\n  WHERE ((t.id = treatment_hives.treatment_id) AND (t.performed_by = auth.uid())))))","create policy \\"treatment_hives_insert\\"\n  on \\"public\\".\\"treatment_hives\\"\n  as permissive\n  for insert\n  to public\nwith check (((EXISTS ( SELECT 1\n   FROM public.treatments t\n  WHERE ((t.id = treatment_hives.treatment_id) AND public.user_can_write_apiary(t.apiary_id)))) AND public.user_can_write_hive(hive_id)))","create policy \\"treatment_hives_select\\"\n  on \\"public\\".\\"treatment_hives\\"\n  as permissive\n  for select\n  to public\nusing ((EXISTS ( SELECT 1\n   FROM public.treatments t\n  WHERE ((t.id = treatment_hives.treatment_id) AND public.user_can_read_apiary(t.apiary_id)))))","create policy \\"treatments_delete\\"\n  on \\"public\\".\\"treatments\\"\n  as permissive\n  for delete\n  to public\nusing (((performed_by = auth.uid()) AND public.user_can_write_apiary(apiary_id)))","create policy \\"treatments_insert\\"\n  on \\"public\\".\\"treatments\\"\n  as permissive\n  for insert\n  to public\nwith check ((public.user_can_write_apiary(apiary_id) AND (performed_by = auth.uid())))","create policy \\"treatments_select\\"\n  on \\"public\\".\\"treatments\\"\n  as permissive\n  for select\n  to public\nusing (public.user_can_read_apiary(apiary_id))","create policy \\"treatments_update\\"\n  on \\"public\\".\\"treatments\\"\n  as permissive\n  for update\n  to public\nusing (((performed_by = auth.uid()) AND public.user_can_write_apiary(apiary_id)))\nwith check (((performed_by = auth.uid()) AND public.user_can_write_apiary(apiary_id)))","CREATE TRIGGER apiaries_set_timestamp BEFORE UPDATE ON public.apiaries FOR EACH ROW EXECUTE FUNCTION public.trigger_set_timestamp()","CREATE TRIGGER harvests_set_timestamp BEFORE UPDATE ON public.harvests FOR EACH ROW EXECUTE FUNCTION public.trigger_set_timestamp()","CREATE TRIGGER hives_set_timestamp BEFORE UPDATE ON public.hives FOR EACH ROW EXECUTE FUNCTION public.trigger_set_timestamp()","CREATE TRIGGER inspections_set_timestamp BEFORE UPDATE ON public.inspections FOR EACH ROW EXECUTE FUNCTION public.trigger_set_timestamp()","CREATE TRIGGER profiles_set_timestamp BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.trigger_set_timestamp()","CREATE TRIGGER queens_set_timestamp BEFORE UPDATE ON public.queens FOR EACH ROW EXECUTE FUNCTION public.trigger_set_timestamp()","CREATE TRIGGER reminders_set_timestamp BEFORE UPDATE ON public.reminders FOR EACH ROW EXECUTE FUNCTION public.trigger_set_timestamp()","CREATE TRIGGER treatments_set_timestamp BEFORE UPDATE ON public.treatments FOR EACH ROW EXECUTE FUNCTION public.trigger_set_timestamp()","drop trigger if exists \\"on_auth_user_created\\" on \\"auth\\".\\"users\\"","CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_user()","drop policy \\"delete apiary media\\" on \\"storage\\".\\"objects\\"","drop policy \\"insert apiary media\\" on \\"storage\\".\\"objects\\"","drop policy \\"read apiary media\\" on \\"storage\\".\\"objects\\"","drop policy \\"update apiary media\\" on \\"storage\\".\\"objects\\"","create policy \\"delete apiary media\\"\n  on \\"storage\\".\\"objects\\"\n  as permissive\n  for delete\n  to public\nusing (((bucket_id = 'apidiario-media'::text) AND public.storage_can_delete_apiary_media(name)))","create policy \\"insert apiary media\\"\n  on \\"storage\\".\\"objects\\"\n  as permissive\n  for insert\n  to public\nwith check (((bucket_id = 'apidiario-media'::text) AND public.storage_can_write_apiary_media(name)))","create policy \\"read apiary media\\"\n  on \\"storage\\".\\"objects\\"\n  as permissive\n  for select\n  to public\nusing (((bucket_id = 'apidiario-media'::text) AND public.storage_can_read_apiary_media(name)))","create policy \\"update apiary media\\"\n  on \\"storage\\".\\"objects\\"\n  as permissive\n  for update\n  to public\nusing (((bucket_id = 'apidiario-media'::text) AND public.storage_can_write_apiary_media(name)))"}	remote_commit
20260512000001	{"create table bloom_observations (\n  id uuid not null default gen_random_uuid(),\n  apiary_id uuid not null references apiaries(id) on delete cascade,\n  species_id text not null references phenology_species(id) on delete cascade,\n  year integer not null,\n  observed_start_date date,\n  observed_end_date date,\n  notes text,\n  user_id uuid not null references auth.users(id) on delete cascade,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n\n  constraint bloom_observations_pkey primary key (id),\n  constraint bloom_observations_unique unique (apiary_id, species_id, year)\n)","alter table bloom_observations enable row level security","create policy \\"users can read own observations\\"\n  on bloom_observations\n  for select\n  using (\n    user_id = auth.uid()\n    or exists (\n      select 1 from apiary_access\n      where apiary_access.apiary_id = bloom_observations.apiary_id\n      and apiary_access.user_id = auth.uid()\n    )\n  )","create policy \\"users can insert own observations\\"\n  on bloom_observations\n  for insert\n  with check (user_id = auth.uid())","create policy \\"users can update own observations\\"\n  on bloom_observations\n  for update\n  using (user_id = auth.uid())","create policy \\"users can delete own observations\\"\n  on bloom_observations\n  for delete\n  using (user_id = auth.uid())","create index idx_bloom_observations_apiary_species_year\n  on bloom_observations (apiary_id, species_id, year)"}	bloom_observations
20260512000002	{"-- Photo/video attachments for inspections\n\nCREATE TABLE IF NOT EXISTS inspection_media (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  inspection_id uuid NOT NULL REFERENCES inspections(id) ON DELETE CASCADE,\n  storage_path text NOT NULL,\n  media_type text NOT NULL CHECK (media_type IN ('image', 'video')),\n  created_at timestamptz NOT NULL DEFAULT now()\n)","CREATE INDEX idx_inspection_media_inspection ON inspection_media(inspection_id)","ALTER TABLE inspection_media ENABLE ROW LEVEL SECURITY","CREATE POLICY inspection_media_select ON inspection_media FOR SELECT\n  USING (EXISTS (\n    SELECT 1 FROM inspections i WHERE i.id = inspection_media.inspection_id\n    AND public.user_can_read_hive(i.hive_id)\n  ))","CREATE POLICY inspection_media_insert ON inspection_media FOR INSERT\n  WITH CHECK (EXISTS (\n    SELECT 1 FROM inspections i WHERE i.id = inspection_media.inspection_id\n    AND public.user_can_write_hive(i.hive_id)\n  ))","CREATE POLICY inspection_media_delete ON inspection_media FOR DELETE\n  USING (EXISTS (\n    SELECT 1 FROM inspections i WHERE i.id = inspection_media.inspection_id\n    AND public.user_can_write_hive(i.hive_id)\n  ))"}	inspection_media
20260512000003	{"-- Storage RLS per inspection media (percorsi inspections/{uuid}/media/{uuid}.{ext})\n-- Le policy esistenti gestiscono solo apiaries/{uuid}/main.{ext}\n\n-- Helper SELECT/INSERT: verifica accesso hive attraverso inspection_id nel path\nCREATE OR REPLACE FUNCTION public.storage_can_read_inspection_media(object_name text)\nRETURNS boolean\nLANGUAGE plpgsql\nSECURITY DEFINER\nSTABLE\nSET search_path = public\nAS $$\nDECLARE\n  parts text[];\n  insp_id uuid;\nBEGIN\n  parts := string_to_array(object_name, '/');\n  IF parts[1] != 'inspections' THEN\n    RETURN FALSE;\n  END IF;\n  insp_id := parts[2]::uuid;\n  RETURN auth.uid() IS NOT NULL\n    AND EXISTS (\n      SELECT 1 FROM inspections i\n      JOIN hives h ON h.id = i.hive_id\n      WHERE i.id = insp_id\n        AND public.user_can_read_hive(h.id)\n    );\nEND;\n$$","CREATE OR REPLACE FUNCTION public.storage_can_write_inspection_media(object_name text)\nRETURNS boolean\nLANGUAGE plpgsql\nSECURITY DEFINER\nSTABLE\nSET search_path = public\nAS $$\nDECLARE\n  parts text[];\n  insp_id uuid;\nBEGIN\n  parts := string_to_array(object_name, '/');\n  IF parts[1] != 'inspections' THEN\n    RETURN FALSE;\n  END IF;\n  insp_id := parts[2]::uuid;\n  RETURN auth.uid() IS NOT NULL\n    AND EXISTS (\n      SELECT 1 FROM inspections i\n      JOIN hives h ON h.id = i.hive_id\n      WHERE i.id = insp_id\n        AND public.user_can_write_hive(h.id)\n    );\nEND;\n$$","CREATE OR REPLACE FUNCTION public.storage_can_delete_inspection_media(object_name text)\nRETURNS boolean\nLANGUAGE plpgsql\nSECURITY DEFINER\nSTABLE\nSET search_path = public\nAS $$\nDECLARE\n  parts text[];\n  insp_id uuid;\nBEGIN\n  parts := string_to_array(object_name, '/');\n  IF parts[1] != 'inspections' THEN\n    RETURN FALSE;\n  END IF;\n  insp_id := parts[2]::uuid;\n  RETURN auth.uid() IS NOT NULL\n    AND (\n      EXISTS (\n        SELECT 1 FROM inspections i\n        JOIN hives h ON h.id = i.hive_id\n        WHERE i.id = insp_id\n          AND public.user_can_write_hive(h.id)\n      )\n      OR EXISTS (\n        SELECT 1 FROM storage.objects\n        WHERE name = object_name\n          AND bucket_id = 'apidiario-media'\n          AND owner = auth.uid()\n      )\n    );\nEND;\n$$","-- Policy per inspection media (additive: OR con policy esistenti)\nCREATE POLICY \\"read inspection media\\"\n  ON storage.objects FOR SELECT\n  USING (bucket_id = 'apidiario-media' AND public.storage_can_read_inspection_media(name))","CREATE POLICY \\"insert inspection media\\"\n  ON storage.objects FOR INSERT\n  WITH CHECK (bucket_id = 'apidiario-media' AND public.storage_can_write_inspection_media(name))","CREATE POLICY \\"update inspection media\\"\n  ON storage.objects FOR UPDATE\n  USING (bucket_id = 'apidiario-media' AND public.storage_can_write_inspection_media(name))","CREATE POLICY \\"delete inspection media\\"\n  ON storage.objects FOR DELETE\n  USING (bucket_id = 'apidiario-media' AND public.storage_can_delete_inspection_media(name))"}	storage_rls_inspection_media
20260513000001	{"-- RPC per ottenere dimensione totale storage bucket\n-- Solo admin puo' chiamarlo (SECURITY DEFINER bypassa RLS)\n\ncreate or replace function get_storage_usage(bucket_name text)\nreturns table (\n  total_size bigint,\n  total_files bigint\n)\nlanguage plpgsql security definer\nas $$\nbegin\n  return query\n  select\n    coalesce(sum((metadata->>'size')::bigint), 0) as total_size,\n    count(*)::bigint as total_files\n  from storage.objects\n  where bucket_id = bucket_name;\nend;\n$$"}	storage_stats
20260513000002	{"CREATE TABLE push_subscriptions (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,\n  endpoint text NOT NULL UNIQUE,\n  keys jsonb NOT NULL,\n  created_at timestamptz NOT NULL DEFAULT now()\n)","ALTER TABLE push_subscriptions ENABLE ROW LEVEL SECURITY","-- Users can manage their own subscriptions\nCREATE POLICY \\"users_manage_own_subscriptions\\"\n  ON push_subscriptions\n  FOR ALL\n  USING (user_id = auth.uid())\n  WITH CHECK (user_id = auth.uid())"}	push_subscriptions
20260513000003	{"-- Fix: SUM(bigint) returns numeric, need explicit ::bigint cast\ncreate or replace function public.get_storage_usage(bucket_name text)\nreturns table (total_size bigint, total_files bigint)\nlanguage plpgsql security definer\nset search_path = ''\nas $$\nbegin\n  return query\n  select\n    coalesce(sum((metadata->>'size')::bigint), 0)::bigint as total_size,\n    count(*)::bigint as total_files\n  from storage.objects\n  where bucket_id = bucket_name;\nend;\n$$"}	fix_storage_stats
20260514000000	{"create table if not exists public.apiary_species (\n  apiary_id uuid not null references apiaries(id) on delete cascade,\n  species_id text not null references phenology_species(id) on delete cascade,\n  created_at timestamptz not null default now(),\n  constraint apiary_species_pkey primary key (apiary_id, species_id)\n)","alter table public.apiary_species enable row level security","-- SELECT: chi può leggere l'apiario può leggere le sue specie\ncreate policy \\"apiary_species_select\\"\n  on public.apiary_species\n  for select\n  using (public.user_can_read_apiary(apiary_id))","-- INSERT: solo il proprietario dell'apiario\ncreate policy \\"apiary_species_insert\\"\n  on public.apiary_species\n  for insert\n  with check (\n    exists (\n      select 1 from apiaries\n      where id = apiary_id and owner_id = auth.uid()\n    )\n  )","-- DELETE: solo il proprietario dell'apiario\ncreate policy \\"apiary_species_delete\\"\n  on public.apiary_species\n  for delete\n  using (\n    exists (\n      select 1 from apiaries\n      where id = apiary_id and owner_id = auth.uid()\n    )\n  )"}	apiary_species
20260514000001	{"ALTER TABLE inspections\n  ADD COLUMN batch_id uuid","CREATE INDEX idx_inspections_batch_id ON inspections(batch_id)\n  WHERE batch_id IS NOT NULL"}	add_batch_id_to_inspections
20260516000001	{"-- Quando un utente viene eliminato, le sue ispezioni/trattamenti/raccolti\n-- su arnie/apiari altrui restano visibili ma con performed_by = NULL.\n-- Questo evita di perdere dati storici e permette la cancellazione dell'utente.\n\n-- inspections\nalter table public.inspections\n  alter column performed_by drop not null","alter table public.inspections\n  drop constraint inspections_performed_by_fkey,\n  add constraint inspections_performed_by_fkey\n    foreign key (performed_by) references public.profiles(id)\n    on delete set null","-- treatments\nalter table public.treatments\n  alter column performed_by drop not null","alter table public.treatments\n  drop constraint treatments_performed_by_fkey,\n  add constraint treatments_performed_by_fkey\n    foreign key (performed_by) references public.profiles(id)\n    on delete set null","-- harvests\nalter table public.harvests\n  alter column recorded_by drop not null","alter table public.harvests\n  drop constraint harvests_recorded_by_fkey,\n  add constraint harvests_recorded_by_fkey\n    foreign key (recorded_by) references public.profiles(id)\n    on delete set null","-- apiary_access.granted_by (chi ha condiviso — bloccava la cancellazione)\nalter table public.apiary_access\n  alter column granted_by drop not null","alter table public.apiary_access\n  drop constraint apiary_access_granted_by_fkey,\n  add constraint apiary_access_granted_by_fkey\n    foreign key (granted_by) references public.profiles(id)\n    on delete set null","-- media.uploaded_by\nalter table public.media\n  alter column uploaded_by drop not null","alter table public.media\n  drop constraint media_uploaded_by_fkey,\n  add constraint media_uploaded_by_fkey\n    foreign key (uploaded_by) references public.profiles(id)\n    on delete set null"}	set_null_on_user_delete
20260602000000	{"-- Owner apiario può cancellare qualsiasi ispezione\n-- Editor può cancellare solo le proprie\n\ndrop policy if exists inspections_delete on public.inspections","create policy inspections_delete on public.inspections\n  for delete using (\n    -- Owner dell'apiario: può cancellare qualsiasi ispezione\n    exists (\n      select 1 from hives h\n      join apiaries a on a.id = h.apiary_id\n      where h.id = inspections.hive_id\n        and a.owner_id = auth.uid()\n    )\n    or (\n      -- Editor: solo le proprie ispezioni, con accesso in scrittura\n      performed_by = auth.uid()\n      and public.user_can_write_hive(hive_id)\n    )\n  )"}	owner_can_delete_any_inspection
20260602000001	{"alter table inspections\n  add column empty_frame_count integer default 0"}	add_empty_frame_count
20260602000002	{"alter table public.phenology_species enable row level security","-- Reference table: any authenticated user can read species list\ncreate policy \\"phenology_species_select\\"\n  on public.phenology_species\n  for select\n  to authenticated\n  using (true)"}	enable_rls_phenology_species
20260602000003	{"create or replace function public.trigger_set_timestamp()\nreturns trigger\nlanguage plpgsql\nsecurity definer set search_path = public\nas $$\nbegin\n  new.updated_at = now();\n  return new;\nend;\n$$"}	secure_trigger_set_timestamp
20260602000004	{"-- SECURITY DEFINER functions callable via RPC must not be executable by anon.\n-- Revoke from PUBLIC (includes anon + authenticated), grant back to authenticated.\n\n-- create_hive_with_queen: used by the app to create hives + first queen atomically\nrevoke execute on function public.create_hive_with_queen from public","grant execute on function public.create_hive_with_queen to authenticated","-- get_storage_usage: used by the statistics page\nrevoke execute on function public.get_storage_usage from public","grant execute on function public.get_storage_usage to authenticated","-- trigger_set_timestamp: only used by triggers, not via RPC — safe to revoke from public\nrevoke execute on function public.trigger_set_timestamp from public","-- RLS helper functions: only used inside SQL policies, not via RPC\nrevoke execute on function public.user_can_read_apiary from public","revoke execute on function public.user_can_write_apiary from public","revoke execute on function public.user_owns_apiary from public","revoke execute on function public.user_can_read_hive from public","revoke execute on function public.user_can_write_hive from public","revoke execute on function public.is_app_admin from public","-- Storage helper functions: only used in storage bucket policies\nrevoke execute on function public.storage_get_apiary_id from public","revoke execute on function public.storage_can_read_apiary_media from public","revoke execute on function public.storage_can_write_apiary_media from public","revoke execute on function public.storage_can_delete_apiary_media from public","revoke execute on function public.storage_can_read_inspection_media from public","revoke execute on function public.storage_can_write_inspection_media from public","revoke execute on function public.storage_can_delete_inspection_media from public"}	revoke_anon_execute_rpc
20260602000005	{"-- Wrap auth.uid() in subquery (select auth.uid()) so pg evaluates it\n-- once per query, not once per row. Supabase dashboard flags this.\n\n-- profiles\ndrop policy if exists profiles_read on public.profiles","create policy profiles_read on public.profiles\n  for select using ((select auth.uid()) is not null)","drop policy if exists profiles_update_self on public.profiles","create policy profiles_update_self on public.profiles\n  for update using (id = (select auth.uid()))\n  with check (id = (select auth.uid()))","-- apiaries\ndrop policy if exists apiaries_insert on public.apiaries","create policy apiaries_insert on public.apiaries\n  for insert with check (owner_id = (select auth.uid()))","-- apiary_access\ndrop policy if exists apiary_access_select on public.apiary_access","create policy apiary_access_select on public.apiary_access\n  for select using (\n    user_id = (select auth.uid())\n    or public.user_owns_apiary(apiary_id)\n  )","-- inspections\ndrop policy if exists inspections_insert on public.inspections","create policy inspections_insert on public.inspections\n  for insert with check (\n    public.user_can_write_hive(hive_id)\n    and performed_by = (select auth.uid())\n  )","drop policy if exists inspections_update on public.inspections","create policy inspections_update on public.inspections\n  for update using (\n    performed_by = (select auth.uid())\n    and public.user_can_write_hive(hive_id)\n  ) with check (\n    performed_by = (select auth.uid())\n    and public.user_can_write_hive(hive_id)\n  )","drop policy if exists inspections_delete on public.inspections","create policy inspections_delete on public.inspections\n  for delete using (\n    exists (\n      select 1 from hives h\n      join apiaries a on a.id = h.apiary_id\n      where h.id = inspections.hive_id\n        and a.owner_id = (select auth.uid())\n    )\n    or (\n      performed_by = (select auth.uid())\n      and public.user_can_write_hive(hive_id)\n    )\n  )","-- treatments\ndrop policy if exists treatments_insert on public.treatments","create policy treatments_insert on public.treatments\n  for insert with check (\n    public.user_can_write_apiary(apiary_id)\n    and performed_by = (select auth.uid())\n  )","drop policy if exists treatments_update on public.treatments","create policy treatments_update on public.treatments\n  for update using (\n    performed_by = (select auth.uid())\n    and public.user_can_write_apiary(apiary_id)\n  ) with check (\n    performed_by = (select auth.uid())\n    and public.user_can_write_apiary(apiary_id)\n  )","drop policy if exists treatments_delete on public.treatments","create policy treatments_delete on public.treatments\n  for delete using (\n    performed_by = (select auth.uid())\n    and public.user_can_write_apiary(apiary_id)\n  )","-- treatment_hives\ndrop policy if exists treatment_hives_delete on public.treatment_hives","create policy treatment_hives_delete on public.treatment_hives\n  for delete using (\n    exists (\n      select 1 from treatments t\n      where t.id = treatment_hives.treatment_id\n        and t.performed_by = (select auth.uid())\n    )\n  )","-- harvests\ndrop policy if exists harvests_insert on public.harvests","create policy harvests_insert on public.harvests\n  for insert with check (\n    public.user_can_write_apiary(apiary_id)\n    and recorded_by = (select auth.uid())\n  )","drop policy if exists harvests_update on public.harvests","create policy harvests_update on public.harvests\n  for update using (\n    recorded_by = (select auth.uid())\n    and public.user_can_write_apiary(apiary_id)\n  ) with check (\n    recorded_by = (select auth.uid())\n    and public.user_can_write_apiary(apiary_id)\n  )","drop policy if exists harvests_delete on public.harvests","create policy harvests_delete on public.harvests\n  for delete using (\n    recorded_by = (select auth.uid())\n    and public.user_can_write_apiary(apiary_id)\n  )","-- reminders\ndrop policy if exists reminders_all on public.reminders","create policy reminders_all on public.reminders\n  for all using (user_id = (select auth.uid()))\n  with check (user_id = (select auth.uid()))","-- media\ndrop policy if exists media_insert on public.media","create policy media_insert on public.media\n  for insert with check (\n    uploaded_by = (select auth.uid())\n    and case\n      when apiary_id     is not null then public.user_can_write_apiary(apiary_id)\n      when hive_id       is not null then public.user_can_write_hive(hive_id)\n      when inspection_id is not null then exists (\n        select 1 from inspections i\n        where i.id = media.inspection_id\n          and public.user_can_write_hive(i.hive_id)\n      )\n      else false\n    end\n  )","drop policy if exists media_delete on public.media","create policy media_delete on public.media\n  for delete using (\n    uploaded_by = (select auth.uid())\n    or case\n      when apiary_id     is not null then public.user_owns_apiary(apiary_id)\n      when hive_id       is not null then exists (\n        select 1 from hives h\n        where h.id = media.hive_id\n          and public.user_owns_apiary(h.apiary_id)\n      )\n      when inspection_id is not null then exists (\n        select 1 from inspections i\n        join hives h on h.id = i.hive_id\n        where i.id = media.inspection_id\n          and public.user_owns_apiary(h.apiary_id)\n      )\n      else false\n    end\n  )","-- bloom_observations\ndrop policy if exists \\"users can read own observations\\" on bloom_observations","create policy \\"users can read own observations\\"\n  on bloom_observations\n  for select\n  using (\n    user_id = (select auth.uid())\n    or exists (\n      select 1 from apiary_access\n      where apiary_access.apiary_id = bloom_observations.apiary_id\n      and apiary_access.user_id = (select auth.uid())\n    )\n  )","drop policy if exists \\"users can insert own observations\\" on bloom_observations","create policy \\"users can insert own observations\\"\n  on bloom_observations\n  for insert\n  with check (user_id = (select auth.uid()))","drop policy if exists \\"users can update own observations\\" on bloom_observations","create policy \\"users can update own observations\\"\n  on bloom_observations\n  for update\n  using (user_id = (select auth.uid()))","drop policy if exists \\"users can delete own observations\\" on bloom_observations","create policy \\"users can delete own observations\\"\n  on bloom_observations\n  for delete\n  using (user_id = (select auth.uid()))","-- push_subscriptions\ndrop policy if exists \\"users_manage_own_subscriptions\\" on public.push_subscriptions","create policy \\"users_manage_own_subscriptions\\" on public.push_subscriptions\n  for all\n  using (user_id = (select auth.uid()))\n  with check (user_id = (select auth.uid()))"}	optimize_rls_auth_uid
20260602000006	{"-- Supabase grants EXECUTE directly to anon for all functions by default.\n-- Revoke from anon for SECURITY DEFINER functions not meant for public.\n-- authenticated retains EXECUTE for functions called via supabase.rpc().\n\n-- App RPC functions (called via supabase.rpc())\nrevoke execute on function public.create_hive_with_queen from anon","revoke execute on function public.get_storage_usage from anon","-- trigger & internal functions\nrevoke execute on function public.trigger_set_timestamp from anon","revoke execute on function public.handle_new_user from anon","-- RLS helper functions\nrevoke execute on function public.user_can_read_apiary from anon","revoke execute on function public.user_can_write_apiary from anon","revoke execute on function public.user_owns_apiary from anon","revoke execute on function public.user_can_read_hive from anon","revoke execute on function public.user_can_write_hive from anon","revoke execute on function public.is_app_admin from anon","-- Storage helper functions\nrevoke execute on function public.storage_get_apiary_id from anon","revoke execute on function public.storage_can_read_apiary_media from anon","revoke execute on function public.storage_can_write_apiary_media from anon","revoke execute on function public.storage_can_delete_apiary_media from anon","revoke execute on function public.storage_can_read_inspection_media from anon","revoke execute on function public.storage_can_write_inspection_media from anon","revoke execute on function public.storage_can_delete_inspection_media from anon"}	revoke_anon_direct_execute
20260602000007	{"alter table public.hives\n  add column main_photo_path text"}	add_hive_main_photo
20260602000008	{"-- Storage RLS policies for hive media (hives/{hive_id}/... paths)\n\n-- 1. Helper READ: user can read hive\nCREATE OR REPLACE FUNCTION public.storage_can_read_hive_media(object_name text)\nRETURNS boolean\nLANGUAGE plpgsql\nSECURITY DEFINER\nSTABLE\nSET search_path = public\nAS $$\nDECLARE\n  parts text[];\n  hive_id uuid;\nBEGIN\n  parts := string_to_array(object_name, '/');\n  IF parts[1] != 'hives' THEN\n    RETURN FALSE;\n  END IF;\n  hive_id := parts[2]::uuid;\n  RETURN public.user_can_read_hive(hive_id);\nEND;\n$$","-- 2. Helper WRITE: user can write hive\nCREATE OR REPLACE FUNCTION public.storage_can_write_hive_media(object_name text)\nRETURNS boolean\nLANGUAGE plpgsql\nSECURITY DEFINER\nSTABLE\nSET search_path = public\nAS $$\nDECLARE\n  parts text[];\n  hive_id uuid;\nBEGIN\n  parts := string_to_array(object_name, '/');\n  IF parts[1] != 'hives' THEN\n    RETURN FALSE;\n  END IF;\n  hive_id := parts[2]::uuid;\n  RETURN public.user_can_write_hive(hive_id);\nEND;\n$$","-- 3. Helper DELETE: owner of the apiary that owns the hive\nCREATE OR REPLACE FUNCTION public.storage_can_delete_hive_media(object_name text)\nRETURNS boolean\nLANGUAGE plpgsql\nSECURITY DEFINER\nSTABLE\nSET search_path = public\nAS $$\nDECLARE\n  parts text[];\n  hive_id uuid;\nBEGIN\n  parts := string_to_array(object_name, '/');\n  IF parts[1] != 'hives' THEN\n    RETURN FALSE;\n  END IF;\n  hive_id := parts[2]::uuid;\n  RETURN EXISTS (\n    SELECT 1 FROM hives h\n    JOIN apiaries a ON a.id = h.apiary_id\n    WHERE h.id = hive_id\n      AND a.owner_id = (select auth.uid())\n  );\nEND;\n$$","-- 4. Storage policies for hive media\nCREATE POLICY \\"read hive media\\"\n  ON storage.objects FOR SELECT\n  USING (bucket_id = 'apidiario-media' AND public.storage_can_read_hive_media(name))","CREATE POLICY \\"insert hive media\\"\n  ON storage.objects FOR INSERT\n  WITH CHECK (bucket_id = 'apidiario-media' AND public.storage_can_write_hive_media(name))","CREATE POLICY \\"update hive media\\"\n  ON storage.objects FOR UPDATE\n  USING (bucket_id = 'apidiario-media' AND public.storage_can_write_hive_media(name))","CREATE POLICY \\"delete hive media\\"\n  ON storage.objects FOR DELETE\n  USING (bucket_id = 'apidiario-media' AND public.storage_can_delete_hive_media(name))"}	storage_rls_hive_media
20260602000009	{"-- Fix activity_log INSERT RLS: allow authenticated users to insert only own logs\ndrop policy if exists \\"service can insert logs\\" on public.activity_log","create policy \\"authenticated can insert own logs\\"\n  on public.activity_log\n  for insert\n  to authenticated\n  with check (user_id = (select auth.uid()))"}	fix_activity_log_rls
20260602000010	{"-- Revoke EXECUTE from anon for SECURITY DEFINER functions.\n-- This prevents unauthenticated calls via /rest/v1/rpc/... while keeping\n-- the functions usable by triggers, internal RLS policy checks, and\n-- authenticated supabase.rpc() calls.\n\n-- handle_new_user: trigger function called by auth.users INSERT.\n--   Must stay SECURITY DEFINER to insert into profiles before session is established.\n--   Should NOT be callable via RPC — anon must be revoked.\nrevoke execute on function public.handle_new_user from anon, public","-- Hive media storage helpers (added in 20260602000008)\nrevoke execute on function public.storage_can_read_hive_media from anon, public","revoke execute on function public.storage_can_write_hive_media from anon, public","revoke execute on function public.storage_can_delete_hive_media from anon, public"}	revoke_anon_security_definer
20260602000011	{"-- Revoke EXECUTE from authenticated for SECURITY DEFINER functions that are\n-- used only internally (triggers, RLS policy helpers).\n-- The caller is never a user via supabase.rpc().\n--\n-- KEPT as authenticated-executable (called via supabase.rpc() from the app):\n--   create_hive_with_queen  — atomic create hive + queen\n--   get_storage_usage       — statistics page\n--   is_app_admin            — admin check in settings\n\n-- Trigger-only functions\nrevoke execute on function public.handle_new_user from authenticated","revoke execute on function public.trigger_set_timestamp from authenticated","-- RLS helper functions (used only inside SQL policies, never via RPC)\nrevoke execute on function public.user_can_read_apiary from authenticated","revoke execute on function public.user_can_write_apiary from authenticated","revoke execute on function public.user_owns_apiary from authenticated","revoke execute on function public.user_can_read_hive from authenticated","revoke execute on function public.user_can_write_hive from authenticated","-- Storage helper functions (used only in storage bucket policies)\nrevoke execute on function public.storage_can_read_apiary_media from authenticated","revoke execute on function public.storage_can_write_apiary_media from authenticated","revoke execute on function public.storage_can_delete_apiary_media from authenticated","revoke execute on function public.storage_can_read_hive_media from authenticated","revoke execute on function public.storage_can_write_hive_media from authenticated","revoke execute on function public.storage_can_delete_hive_media from authenticated","revoke execute on function public.storage_can_read_inspection_media from authenticated","revoke execute on function public.storage_can_write_inspection_media from authenticated","revoke execute on function public.storage_can_delete_inspection_media from authenticated"}	revoke_authenticated_security_definer_rls
20260611000003	{"-- ⚠️ DA APPLICARE SOLO DOPO aver verificato che la conversione dati\n--    (is_marked + birth_year) della migration 20260611000001 è corretta.\n--\n-- Per applicarla:\n--   1. Sposta questo file in supabase/migrations/\n--   2. npx supabase db push  (o psql -f con la connection string)\n--\n-- Drop irreversibile. L'enum queen_marking_color resta: è usato lato app\n-- come tipo del colore derivato dall'anno di nascita.\n\nALTER TABLE public.queens\n  DROP COLUMN marking_color"}	drop_queen_marking_color
20260605000001	{"-- Ripristina EXECUTE per authenticated sulle funzioni SECURITY DEFINER\n-- usate dalle RLS policy (sia table RLS che storage bucket RLS).\n--\n-- La migration 20260602000011 ha revocato erroneamente authenticated,\n-- causando \\"permission denied for function\\" quando le policy RLS\n-- valutano queste funzioni per un utente autenticato.\n--\n-- Trigger-only (handle_new_user, trigger_set_timestamp) rimangono\n-- revocate — i trigger girano come owner della tabella, non come authenticated.\n\n-- RLS helper functions\ngrant execute on function public.user_can_read_apiary to authenticated","grant execute on function public.user_can_write_apiary to authenticated","grant execute on function public.user_owns_apiary to authenticated","grant execute on function public.user_can_read_hive to authenticated","grant execute on function public.user_can_write_hive to authenticated","-- Storage helper functions\ngrant execute on function public.storage_can_read_apiary_media to authenticated","grant execute on function public.storage_can_write_apiary_media to authenticated","grant execute on function public.storage_can_delete_apiary_media to authenticated","grant execute on function public.storage_can_read_hive_media to authenticated","grant execute on function public.storage_can_write_hive_media to authenticated","grant execute on function public.storage_can_delete_hive_media to authenticated","grant execute on function public.storage_can_read_inspection_media to authenticated","grant execute on function public.storage_can_write_inspection_media to authenticated","grant execute on function public.storage_can_delete_inspection_media to authenticated"}	restore_authenticated_rls_helper_exec
20260607000001	{"-- Replace queen_cells enum column with has_queen_cells toggle + jsonb types\nalter table public.inspections\n  add column has_queen_cells boolean not null default false,\n  add column queen_cell_types jsonb not null default '[]'::jsonb,\n  drop column queen_cells"}	rework_queen_cells
20260608000000	{"create table public.user_inspection_preferences (\n  user_id uuid primary key references auth.users(id) on delete cascade,\n  express_fields jsonb not null default '[\\"queen\\",\\"hasBrood\\",\\"population\\",\\"hasQueenCells\\",\\"notes\\"]'::jsonb,\n  updated_at timestamptz not null default now()\n)","alter table public.user_inspection_preferences enable row level security","create policy \\"Users can read own preferences\\"\n  on public.user_inspection_preferences for select\n  using (auth.uid() = user_id)","create policy \\"Users can upsert own preferences\\"\n  on public.user_inspection_preferences for insert\n  with check (auth.uid() = user_id)","create policy \\"Users can update own preferences\\"\n  on public.user_inspection_preferences for update\n  using (auth.uid() = user_id)"}	user_inspection_preferences
20260608000001	{"-- Admin-only statistics functions\n\n-- Active user counts (7d and 30d) from activity_log\ncreate or replace function public.get_active_user_counts()\nreturns table(active_7d bigint, active_30d bigint)\nlanguage sql\nsecurity definer\nset search_path = public\nas $$\n  select\n    count(distinct case when created_at >= now() - interval '7 days' then user_id end) as active_7d,\n    count(distinct case when created_at >= now() - interval '30 days' then user_id end) as active_30d\n  from activity_log\n  where created_at >= now() - interval '30 days';\n$$","revoke execute on function public.get_active_user_counts from public, anon, authenticated","grant execute on function public.get_active_user_counts to authenticated","-- Weekly inspection counts for the last N weeks\ncreate or replace function public.get_weekly_inspection_counts(weeks_back int default 8)\nreturns table(week_start date, count bigint)\nlanguage sql\nsecurity definer\nset search_path = public\nas $$\n  select\n    date_trunc('week', performed_at)::date as week_start,\n    count(*) as count\n  from inspections\n  where performed_at >= date_trunc('week', now()) - ((weeks_back - 1) * interval '1 week')\n  group by date_trunc('week', performed_at)\n  order by week_start;\n$$","revoke execute on function public.get_weekly_inspection_counts from public, anon, authenticated","grant execute on function public.get_weekly_inspection_counts to authenticated","-- Per-user activity stats\ncreate or replace function public.get_user_activity_stats()\nreturns table(\n  user_id uuid,\n  display_name text,\n  inspection_count bigint,\n  last_inspection_at timestamptz,\n  last_active_at timestamptz\n)\nlanguage sql\nsecurity definer\nset search_path = public\nas $$\n  select\n    p.id as user_id,\n    p.display_name,\n    count(distinct i.id) as inspection_count,\n    max(i.performed_at) as last_inspection_at,\n    max(al.created_at) as last_active_at\n  from profiles p\n  left join inspections i on i.performed_by = p.id\n  left join activity_log al on al.user_id = p.id\n  group by p.id, p.display_name\n  order by last_active_at desc nulls last\n  limit 50;\n$$","revoke execute on function public.get_user_activity_stats from public, anon, authenticated","grant execute on function public.get_user_activity_stats to authenticated"}	admin_stats_functions
20260611000000	{"-- =====================================================================\n-- Migrazione: impedisce la rimozione dell'ultimo amministratore\n-- =====================================================================\n-- La policy app_admins_delete consente a qualsiasi admin di cancellare\n-- righe (anche la propria) via client, bypassando la edge function\n-- admin-remove-admin. Senza protezione DB si può svuotare del tutto\n-- app_admins → lockout amministrativo irreversibile.\n--\n-- Trigger BEFORE DELETE: blocca l'eliminazione se lascerebbe 0 admin.\n-- =====================================================================\n\ncreate or replace function public.prevent_last_admin_removal()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if (select count(*) from public.app_admins) <= 1 then\n    raise exception 'Impossibile rimuovere l''ultimo amministratore';\n  end if;\n  return old;\nend;\n$$","drop trigger if exists trg_prevent_last_admin_removal on public.app_admins","create trigger trg_prevent_last_admin_removal\n  before delete on public.app_admins\n  for each row execute function public.prevent_last_admin_removal()"}	prevent_last_admin_removal
20260611000001	{"-- Regina: sostituisce `marking_color` con un flag `is_marked`.\n-- Il colore di marcatura non è più memorizzato: si ricava dall'anno di nascita\n-- seguendo la convenzione internazionale (cifra finale dell'anno → colore).\n--\n-- Conversione dati esistenti:\n--   1. is_marked = (marking_color <> 'non_marcata')\n--   2. birth_year (SOLO dove NULL e marcata) = anno più recente <= anno corrente\n--      la cui cifra finale corrisponde al colore. Dove birth_year è già\n--      valorizzato viene mantenuto (precedenza all'anno esistente).\n\n-- 1. Nuova colonna\nALTER TABLE public.queens\n  ADD COLUMN is_marked boolean NOT NULL DEFAULT false","-- 2. Backfill flag marcata\nUPDATE public.queens\nSET is_marked = (marking_color <> 'non_marcata')","-- 3. Backfill anno di nascita solo dove mancante e regina marcata.\n--    Per ogni colore: anno = max tra gli anni <= corrente che finiscono con\n--    una delle due cifre della convenzione.\n--    Formula: candidato(e) = Y - ((Y%10 - e + 10) % 10)  → anno <= Y che finisce in e.\nUPDATE public.queens AS q\nSET birth_year = (\n  WITH y AS (SELECT (extract(year FROM current_date))::int AS yy)\n  SELECT CASE q.marking_color\n    WHEN 'bianco' THEN GREATEST(yy - ((yy % 10 - 1 + 10) % 10), yy - ((yy % 10 - 6 + 10) % 10))\n    WHEN 'giallo' THEN GREATEST(yy - ((yy % 10 - 2 + 10) % 10), yy - ((yy % 10 - 7 + 10) % 10))\n    WHEN 'rosso'  THEN GREATEST(yy - ((yy % 10 - 3 + 10) % 10), yy - ((yy % 10 - 8 + 10) % 10))\n    WHEN 'verde'  THEN GREATEST(yy - ((yy % 10 - 4 + 10) % 10), yy - ((yy % 10 - 9 + 10) % 10))\n    WHEN 'blu'    THEN GREATEST(yy - ((yy % 10 - 5 + 10) % 10), yy - ((yy % 10 - 0 + 10) % 10))\n  END\n  FROM y\n)\nWHERE q.birth_year IS NULL\n  AND q.marking_color <> 'non_marcata'","-- 4. Aggiorna la RPC che crea arnia + prima regina: niente più marking_color.\n--    La nuova regina nasce non marcata (is_marked default false).\nCREATE OR REPLACE FUNCTION public.create_hive_with_queen(\n  p_id               uuid,\n  p_apiary_id        uuid,\n  p_identifier       text,\n  p_hive_type        public.hive_type,\n  p_bee_race         public.bee_race,\n  p_installed_on     date,\n  p_origin_notes     text,\n  p_nido_frame_count smallint,\n  p_notes            text\n)\nRETURNS void\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nBEGIN\n  IF NOT EXISTS (\n    SELECT 1 FROM apiaries WHERE id = p_apiary_id AND owner_id = auth.uid()\n  ) THEN\n    RAISE EXCEPTION 'unauthorized';\n  END IF;\n\n  INSERT INTO hives (\n    id, apiary_id, identifier, hive_type, bee_race,\n    installed_on, origin_notes, nido_frame_count, notes\n  ) VALUES (\n    p_id, p_apiary_id, p_identifier, p_hive_type, p_bee_race,\n    p_installed_on, p_origin_notes, p_nido_frame_count, p_notes\n  );\n\n  INSERT INTO queens (hive_id, origin, start_date)\n  VALUES (p_id, 'sconosciuta', COALESCE(p_installed_on, CURRENT_DATE));\nEND;\n$$","-- NB: la colonna `marking_color` NON viene droppata qui di proposito.\n-- Resta nel DB (ignorata dall'app) finché non si verifica che la conversione\n-- dei dati (is_marked + birth_year) è corretta. Il DROP è in una migration\n-- separata: supabase/migrations-pending/20260611000002_drop_queen_marking_color.sql\n-- da promuovere in migrations/ e applicare solo dopo la verifica."}	queen_is_marked
20260611000002	{"-- Visita: flag \\"Necessario intervento\\". Quando l'ultima visita di un'arnia\n-- ha needs_intervention = true, l'arnia va evidenziata e ordinata per prima\n-- nell'elenco dell'apiario (logica lato app).\n\nALTER TABLE public.inspections\n  ADD COLUMN needs_intervention boolean NOT NULL DEFAULT false"}	inspection_needs_intervention
20260616000001	{"alter table public.user_inspection_preferences\n  add column if not exists suggestion_filters jsonb"}	suggestion_filters
20260617000001	{"alter table public.inspections\n  add column if not exists pending_interventions text[] default '{}'"}	pending_interventions
20260618000001	{"create table public.api_usage_log (\n  id           uuid primary key default gen_random_uuid(),\n  user_id      uuid not null references auth.users(id) on delete cascade,\n  created_at   timestamptz not null default now(),\n  service      text not null check (service in ('whisper', 'deepseek')),\n  audio_seconds numeric(8,2),   -- whisper\n  tokens_in    integer,         -- deepseek\n  tokens_out   integer,         -- deepseek\n  cost_usd     numeric(12,8) not null default 0\n)","create index idx_api_usage_log_user on public.api_usage_log(user_id, created_at desc)","create index idx_api_usage_log_created on public.api_usage_log(created_at desc)","alter table public.api_usage_log enable row level security","create policy \\"users can insert own usage\\"\n  on public.api_usage_log for insert\n  with check (auth.uid() = user_id)","create policy \\"users can read own usage\\"\n  on public.api_usage_log for select\n  using (auth.uid() = user_id)","create policy \\"admins can read all usage\\"\n  on public.api_usage_log for select\n  using (exists (select 1 from public.app_admins where user_id = auth.uid()))","-- Aggregazione per utente (admin only)\ncreate or replace function public.get_api_cost_by_user()\nreturns table (\n  user_id      uuid,\n  display_name text,\n  call_count   bigint,\n  cost_usd     numeric\n)\nlanguage sql\nsecurity definer\nstable\nset search_path = public\nas $$\n  select\n    l.user_id,\n    coalesce(p.display_name, l.user_id::text) as display_name,\n    count(*)::bigint as call_count,\n    sum(l.cost_usd) as cost_usd\n  from api_usage_log l\n  left join profiles p on p.id = l.user_id\n  group by l.user_id, p.display_name\n  order by cost_usd desc;\n$$"}	api_usage_log
